function live(){if(admin())return allTables();let bs=S.bouts||[];return '<div class="eyebrow">24. Oktober 2026 · Nürnberg</div><h1>Tatamis</h1><p class="lead">Starterlisten, laufende Begegnungen und Ergebnisse der Süddeutschen Meisterschaft.</p>'+(S.event.demo?'<p class="note">TESTDATEN · Namen, Dojos und Ergebnisse sind fiktiv.</p>':'')+(!S.event.published&&!S.user?'<div class="banner"><div><h2>Die Listen werden vorbereitet.</h2><p class="muted">Die Gruppenplanung ist bereits vor der Auslosung verfügbar. <a href="#overview">Gruppenübersicht öffnen</a></p></div></div>':'')+metrics()+'<div class="grid">'+S.tatamis.map(t=>{let live=bs.find(b=>b.status==='live'&&mat(b)===t.id),next=bs.filter(b=>b.status==='ready'&&!b.held&&mat(b)===t.id).sort((a,b)=>(a.callRank??1e9)-(b.callRank??1e9)||phase(group(a.group),a)-phase(group(b.group),b)||group(a.group).order-group(b.group).order).slice(0,3);return '<section class="card"><div class="tatami-head"><span class="tatami-number">Tatami '+t.id+'</span><span class="pill '+(live?'live':'')+'">'+(live?'● Läuft':'Bereit')+'</span></div>'+(live?'<h3>'+esc(live.group)+' · '+esc(names[mode(group(live.group),live)])+'</h3><p><strong>'+esc(entrant(live.shiro).name)+' ⚪</strong></p><p><strong>'+esc(entrant(live.aka).name)+' 🔴</strong></p>':'<p class="muted">Aktuell keine Begegnung gestartet</p>')+publicScore(live)+'<small>Als Nächstes</small>'+next.map(b=>'<div class="queue"><b>'+esc(b.group)+'</b> · '+esc(entrant(b.aka).name)+(b.shiro?' / '+esc(entrant(b.shiro).name):'')+'</div>').join('')+(next.length?'':'<p class="muted">Noch keine Begegnungen aufgerufen</p>')+'</section>';}).join('')+'</div><div class="bar"><h2>Livestreams</h2></div><div class="grid">'+streams()+'</div>';}
