function teamPanel(b,t){let fs=b.teamFights||[],live=fs.find(f=>f.status==='live'),n=fs.length,sides=screenSides(t.orientation);let text='<div class="card"><h3>🥋 '+(live?'Einzelkampf '+(live.index+1)+(live.index===3?' · Stichkampf':' / 3'):'Nächster Einzelkampf '+(n+1))+'</h3>';if(live){text+=(live.medicalPending?'<p class="note">Teilnahmesperre · keine Zeitnahme oder Punkte. Über „Aufgabe / DQ / kampfunfähig“ die Entscheidung des Kampfgerichts erfassen.</p>':'');text+='<div class="match '+([90,270].includes(t.orientation)?'vertical':'')+'">'+sides.map(side=>'<div class="side '+side+'"><div class="belt">'+(side==='aka'?'🔴 Aka':'⚪ Shiro')+' <kbd>'+(sides.indexOf(side)===0?'←':'→')+'</kbd></div><div class="name">'+esc(live[side+'Name'])+'</div><div class="score">'+(live.score[side]/2).toLocaleString('de-DE',{minimumFractionDigits:1})+'</div><div class="score-actions"><button data-do="teamScore" data-side="'+side+'" data-value="2">● Ippon<small>voller Punkt</small></button><button class="quiet" data-do="teamScore" data-side="'+side+'" data-value="1">◐ Wazaari<small>halber Punkt</small></button></div><button data-do="teamFinish" data-side="'+side+'">⚑ '+(side==='aka'?'Aka':'Shiro')+' gewinnt Einzelkampf</button>'+quickPenalties(b,side,true)+'<details><summary>⚠ Verwarnungen</summary>'+(live.penalties[side]||[]).map(p=>'<small>'+esc(p.family)+' · '+p.level+'</small>').join('')+'<button class="quiet small-btn" data-do="teamPenalty" data-side="'+side+'">Eintragen</button></details></div>').join('')+'</div><div class="actions">'+(live.index<3?'<button class="quiet" data-do="teamDraw">＝ Hikiwake · Unentschieden</button>':'<button class="quiet" data-do="teamSaishiai">Gleichstand · Saishiai</button>')+'</div>';}else if(b.status==='live'){text+='<button class="green" data-do="teamStart">▶ '+(n===3?'Stichkämpfer wählen und aufrufen':'Einzelkampf '+(n+1)+' aufrufen')+'</button>';}
text+=(!b.started&&b.akaOrder&&b.shiroOrder?'<div class="team-drawn-pairs">'+[0,1,2].map(i=>'<p><b>'+(i+1)+'.</b> Shiro: '+esc(pname(S.people.find(p=>p.id===b.shiroOrder[i])))+' / <span class="aka">Aka: '+esc(pname(S.people.find(p=>p.id===b.akaOrder[i])))+'</span></p>').join('')+'</div>':'');text+='<p>Alle drei Einzelkämpfe werden durchgeführt. Unterbewertung: Siege, dann Ippon-Siege, dann Wazaari der Sieger; danach Stichkampf.</p>'+fs.filter(f=>f.status==='done').map(f=>'<p class="note">Einzelkampf '+(f.index+1)+' · '+esc(f.shiroName)+' ⚪ / '+esc(f.akaName)+' 🔴 · '+esc(f.reason)+' · '+(f.winner==='draw'?'Unentschieden':esc(f[f.winner+'Name']))+'</p>').join('')+'</div>';return text;}

function trainerView(){
 if(!trainer())return denied();
 const teams=S.teams||[],open=teams.filter(t=>!t.verified&&!t.pendingRequest&&!t.locked).length;
 const tasks='<section class="card"><h2>Deine Aufgabe: Teammitglieder auswählen'+(open?' · '+open+' offen':'')+'</h2><p>Wähle für jedes gemeldete Team drei Personen aus. Deine Auswahl wird erst nach Freigabe durch die Wettkampfleitung übernommen.</p>'+teams.map(t=>{
  const status=t.locked?'Wettkampf begonnen · Zuordnung gesperrt':t.pendingRequest?'Auswahl eingereicht · Freigabe ausstehend':t.verified?'Teammitglieder bestätigt':'Zuordnung offen';
  return '<div class="queue"><div class="row"><b>'+esc(t.name)+' · '+esc(t.group)+'</b><span class="pill">'+status+'</span></div><p>'+esc((t.members||[]).join(', '))+'</p>'+(t.pendingRequest?'<p>Vorgeschlagen: '+esc(t.proposedMemberIds.map(id=>t.candidates.find(p=>p.id===id)).map(p=>p?pname(p):'Angaben geändert · erneut prüfen').join(', '))+'</p>':'')+(!t.locked?'<button data-do="trainerTeam" data-id="'+esc(t.id)+'">'+(t.pendingRequest?'Auswahl überarbeiten':t.verified?'Änderung vorschlagen':'Teammitglieder auswählen')+'</button>':'')+'</div>';
 }).join('')+(!teams.length?'<p class="muted">Für dein Dojo sind keine aktiven Teams gemeldet.</p>':'')+'</section>';
 return '<div class="eyebrow">Coachbereich</div><h1>'+esc(S.user.dojo)+'</h1><p class="lead">Kader kennzeichnen, Teammitglieder auswählen und Meldung prüfen. Die Leitung bestätigt Teamänderungen.</p>'+'<p><a class="btn" href="#notify">Aufrufe für mein Dojo aufs Handy</a></p>'+cadreUI.coach()+trainerProgressCard(S)+billingCard(S)+tasks+'<div class="card scroll"><h2>Gemeldete Personen</h2><table><thead><tr><th>Name</th><th>Geburt</th><th>Grad</th><th>Starts</th><th></th></tr></thead><tbody>'+S.people.map(p=>'<tr><td>'+esc(pname(p))+'</td><td>'+esc(p.birth)+'</td><td>'+(p.kyu===0?'Dan':p.kyu+'. Kyu')+'</td><td>'+(S.ownEntries||[]).filter(e=>e.personId===p.id).map(e=>esc(e.group)).join(', ')+'</td><td><button class="quiet small-btn" data-do="request" data-id="'+p.id+'">Korrektur beantragen</button></td></tr>').join('')+'</tbody></table></div>'+requests();
}
