function beep(n){try{let a=new AudioContext();for(let i=0;i<n;i++){let osc=a.createOscillator(),gain=a.createGain();osc.connect(gain);gain.connect(a.destination);osc.frequency.value=880;gain.gain.value=.12;osc.start(a.currentTime+i*.4);osc.stop(a.currentTime+i*.4+.2);}setTimeout(()=>a.close(),1500);}catch{}}
