function jobKey(b){return b.group+'|'+phase(group(b.group),b)+'|'+(b.pool?'p'+b.pool:'f');}
function jobRank(b){let i=(S.queue||[]).findIndex(q=>q.id===jobKey(b));return i<0?1e9:i;}
function entryRoute(e){let b=S.bouts.find(b=>b.group===e.group&&(b.aka===e.id||b.shiro===e.id)&&!b.sources?.length);return b?{pool:b.pool,tatami:mat(b)}:{pool:null,tatami:group(e.group)?.tatami};}
function issueBanner(){let issues=S.issues||[];return issues.length?'<div class="review-alert"><b>'+issues.length+' Angaben prüfen</b>'+issues.map(x=>'<p><button class="quiet small-btn" data-do="person" data-id="'+esc(x.person)+'">'+esc(x.name)+'</button> · '+esc(x.dojo)+'<small>'+esc(x.reason)+(x.group?' · '+esc(x.group):'')+'</small></p>').join('')+'</div>':'';}
