 if(!admin())return denied();const matches=value=>!query||value.toLocaleLowerCase('de').includes(query.toLocaleLowerCase('de')),people=S.people.filter(p=>(!dojoFilter||p.dojo===dojoFilter)&&matches(pname(p)+' '+p.dojo)&&(!rosterGroup||personStarts(p).some(e=>e.group===rosterGroup))&&(!disciplineFilter||personStarts(p).some(e=>String(group(e.group)?.type)===disciplineFilter))),teams=S.teams.filter(t=>(!dojoFilter||t.dojo===dojoFilter)&&matches(t.name+' '+t.dojo+' '+t.members.join(' '))&&(!rosterGroup||S.entries.some(e=>e.active&&e.personId===t.id&&e.group===rosterGroup))&&(!disciplineFilter||S.entries.some(e=>e.active&&e.personId===t.id&&String(group(e.group)?.type)===disciplineFilter))),dojos=S.dojos.filter(d=>(!dojoFilter||d.name===dojoFilter)&&(!(query||rosterGroup||disciplineFilter)||people.some(p=>p.dojo===d.name)||teams.some(t=>t.dojo===d.name))),names=new Set(dojos.map(d=>d.name)),rows=dojoOverview(S).filter(r=>names.has(r.name));
