function queueBoard(){
 const qs=(S.queue||[]).filter(q=>q.status!=='done');if(!qs.length)return '<section class="card"><h2>Poolplanung</h2><p>Derzeit sind keine offenen Pools eingeplant.</p></section>';
 const periodLabels={morning:'Vormittag',afternoon:'Nachmittag'},laneTitles=['Kata-Team · 8–11','Kata Einzel · bis 12','Kumite Einzel · bis 12','Kata-Team / Kata Einzel','Kumite Einzel · ab 13','Finals · ab 13 / Kata-Team','Kumite-Team'];
 const undoAllowed=queueUndo&&!queueSaving&&(S.queueRevision||0)===queueUndo.afterRevision&&qs.some(q=>q.id===queueUndo.job)&&(!queueUndo.before||qs.some(q=>q.id===queueUndo.before));
 const legend='<div class="queue-legend" aria-label="Farblegende">'+disciplineStyles.map(d=>'<span class="discipline-chip discipline-'+d.key+'">'+d.label+'</span>').join('')+'<span class="legend-divider" aria-hidden="true">·</span>'+Object.values(genderStyles).map(g=>'<span class="gender-chip gender-'+g.key+'">'+g.label+'</span>').join('')+'</div>';
 return '<section class="queue-planner" id="pool-planner" aria-labelledby="queue-title"><div class="bar"><div><h2 id="queue-title">Pools auf Tatami 1–5 planen</h2><p class="rules" id="queue-help">'+(admin()?'Pool am Griff ⋮⋮ ziehen. Die Einfügelinie zeigt die neue Position. Innerhalb einer Wettkampfphase frei sortieren und zwischen Tatamis verschieben.':'Reihenfolge der Wettkampfleitung.')+'</p></div>'+(admin()?'<div class="actions"><button class="quiet small-btn" data-write data-do="autoPlan" data-unavailable="'+(queueSaving?'1':'0')+'">Nach Starterzahl verteilen</button>'+(queueUndo?'<button class="quiet small-btn" data-write data-do="queueUndo" data-unavailable="'+(undoAllowed?'0':'1')+'" '+(!undoAllowed?'disabled':'')+'>Letzte Verschiebung rückgängig</button>':'')+'</div>':'')+'</div>'+legend+'<p id="queue-drag-message" class="queue-drag-message" role="status" aria-live="polite">'+(queueSaving?'Neue Pool-Reihenfolge wird gespeichert …':'Die Tischansichten übernehmen die gespeicherte Reihenfolge. Laufende Kämpfe behalten ihre Tatami.')+'</p>'+['morning','afternoon'].map(period=>{const ps=period==='morning'?[0,1,2]:[3,4,5,6],jobs=qs.filter(q=>queuePeriod(q.phase)===period);return '<section class="queue-period period-'+period+'" data-queue-period="'+period+'"><div class="queue-period-heading"><h3>'+periodLabels[period]+'</h3><span>'+(period==='morning'?'Ab 10:00 · bis zur Siegerehrung und Mittagspause':'Ab 13:30 · bis zu den Teamwettkämpfen')+' · '+jobs.length+' offene Pools / Finalrunden</span></div><div class="tatami-board queue-board">'+S.tatamis.map(t=>{const next=qs.find(q=>q.tatami===t.id),live=S.bouts.find(b=>b.status==='live'&&mat(b)===t.id&&queuePeriod(phase(group(b.group),b))===period);return '<section class="tatami-column"><div class="queue-tatami-heading"><h4>Tatami '+t.id+'</h4><span>'+jobs.filter(q=>q.tatami===t.id).length+' Pools</span></div>'+(live?'<div class="live-pool"><b>Läuft: '+esc(live.group)+'</b><small>'+esc(entrant(live.aka).name)+(live.shiro?' / '+esc(entrant(live.shiro).name):'')+'</small></div>':'')+ps.map(p=>{const items=jobs.filter(q=>q.tatami===t.id&&q.phase===p);return '<section class="queue-lane" data-queue-lane data-queue-tatami="'+t.id+'" data-queue-phase="'+p+'" aria-label="Tatami '+t.id+' · '+esc(phases[p])+'"><h5><time>'+esc(DAY.phaseStarts?.[p]||'')+'</time> '+laneTitles[p]+'</h5>'+items.map((q,index)=>queueCard(q,index,next?.id)).join('')+'<div class="queue-drop-end" data-queue-end><span>'+(items.length?'Hier am Ende ablegen':'Freier Platz · Pool hier ablegen')+'</span></div></section>';}).join('')+'</section>';}).join('')+'</div></section>';}).join('')+'</section>';
}
function queueCard(q,index,nextId){
 const g=group(q.group),discipline=disciplineStyles[g.type]||disciplineStyles[0],gender=genderStyles[g.gender]||genderStyles.x,draggable=admin()&&online&&!queueSaving;
 return '<article class="pool-card discipline-'+discipline.key+'" draggable="'+draggable+'" data-queue-job="'+esc(q.id)+'" data-queue-tatami="'+q.tatami+'" data-queue-phase="'+q.phase+'" aria-describedby="queue-help"><div class="pool-card-heading"><span class="pool-drag-handle" aria-hidden="true" title="Pool ziehen">⋮⋮</span><b>'+esc(q.group)+' · '+poolLabel(q)+'</b><span class="queue-position">'+(index+1)+'</span></div><div class="pool-card-tags"><span class="discipline-chip discipline-'+discipline.key+'">'+discipline.label+'</span><span class="gender-chip gender-'+gender.key+'">'+gender.label+'</span></div><p class="pool-age">'+esc(groupAge(g))+' · '+esc(groupGrade(g))+'</p><p>'+q.count+' Starts · '+(q.drawn?q.remaining+' Begegnungen offen':'noch nicht ausgelost')+'</p><span class="queue-card-state">'+(q.status==='live'?'● Begegnung läuft':q.id===nextId?'Als Nächstes':q.anticipated?'Finalrunde vorgemerkt':'Eingeplant')+'</span>'+(q.liveTatamis?.some(t=>t!==q.tatami)?'<small class="warning-text">Laufender Kampf auf Tatami '+q.liveTatamis.join(', ')+'</small>':'')+(admin()?releaseButton(S,q):'')+'<div class="actions no-print"><button class="quiet small-btn" data-do="poolSheet" data-id="'+esc(q.group)+'" data-pool="'+(q.pool||0)+'">Starterliste</button>'+(admin()?'<button class="quiet small-btn" data-write data-unavailable="'+(queueSaving?'1':'0')+'" aria-label="'+esc(q.group)+' nach oben" data-do="queueUp" data-id="'+esc(q.id)+'">↑</button><button class="quiet small-btn" data-write data-unavailable="'+(queueSaving?'1':'0')+'" aria-label="'+esc(q.group)+' nach unten" data-do="queueDown" data-id="'+esc(q.id)+'">↓</button><button class="quiet small-btn" data-write data-unavailable="'+(queueSaving?'1':'0')+'" data-do="queueMove" data-id="'+esc(q.id)+'">Tatami ändern</button><button class="quiet small-btn" data-practical-action="assignFree" data-job="'+esc(q.id)+'">Auf freie Tatami</button><button class="quiet small-btn" data-practical-action="plan" data-group="'+esc(q.group)+'">Ablauf / Finale</button><button class="quiet small-btn" data-practical-action="'+(q.held?'resume':'defer')+'" data-job="'+esc(q.id)+'">'+(q.held?'Fortsetzen':'Zurückstellen')+'</button>':'')+'</div></article>';
}

function sheetView(){let g=group(selectedGroup);if(!g)return lists();let all=S.bouts.filter(b=>b.group===g.code),pools=[...new Set(all.map(b=>b.pool||0))].sort((a,b)=>a===0?1:b===0?-1:a-b),entries=S.entries.filter(e=>e.active&&e.group===g.code),num=id=>all.findIndex(b=>b.id===(typeof id==='object'?id.id:id))+1;
if(!pools.length)pools=[0];let choose=pools.filter(p=>reportPool===''||p===Number(reportPool));
function participant(b,side){let id=b[side],src=b.sources?.[side==='aka'?0:1];if(id){let e=entrant(id);return '<b>'+esc(e.name)+'</b><small>'+esc(e.dojo)+'</small>';}return '<span class="muted">'+(src?(b.fromLoser?'Verlierer':'Sieger')+' Kampf '+num(src):'Freilos / noch offen')+'</span>';}
return '<div class="bar no-print"><div><h1>Wettkampfliste · '+esc(g.code)+'</h1></div><div class="actions"><select id="group-filter"><option value="">Gruppe auswählen</option>'+options(S.groups.filter(g=>g.active&&S.entries.some(e=>e.group===g.code)),g.code,'code',g=>g.code+' · '+S.entries.filter(e=>e.active&&e.group===g.code).length+' '+(g.type>=2?'Teams':'Starter'))+'</select><select id="report-pool"><option value="">Alle Pools und Finale</option>'+pools.map(p=>'<option value="'+p+'" '+(reportPool!==''&&Number(reportPool)===p?'selected':'')+'>'+(p?'Pool '+p:'Finalrunde')+'</option>').join('')+'</select><button class="quiet" data-practical-action="printOne" data-group="'+esc(g.code)+'"'+(reportPool!==''?' data-pool="'+esc(reportPool)+'"':'')+'>A4-PDF</button>'+(admin()?'<button class="quiet" data-practical-action="obmannOne" data-group="'+esc(g.code)+'">Obmann-Protokoll</button>':'')+'<a class="btn quiet" href="#printing">Mehrere Listen drucken</a>'+ (admin()&&g.draw?'<button class="quiet" data-do="swap" data-id="'+esc(g.code)+'">Starter tauschen</button>':'')+'<a class="btn quiet" href="#lists">Alle Starter</a></div></div>'+choose.map(p=>{let bs=all.filter(b=>(b.pool||0)===p),first=bs[0],routes=[...new Set(bs.filter(b=>b.status!=='done').map(mat))],rounds=[...new Set(bs.filter(b=>b.kind!=='points').map(b=>b.round||0))].sort((a,b)=>a-b),points=bs.filter(b=>b.kind==='points'),ids=[...new Set(bs.filter(b=>!b.sources?.length).flatMap(b=>[b.aka,b.shiro]).filter(Boolean))];return '<section class="competition-sheet"><header class="sheet-header"><div><strong>DJKB · Süddeutsche Meisterschaft des DJKB 2026</strong><h2>'+esc(g.code)+' · '+(p?'Pool '+p:'Finalrunde')+'</h2></div><div><b>'+ (routes.length?'Tatami '+routes.join(' / '):first?'Tatami '+mat(first):'Tatami '+g.tatami)+'</b><small>24.10.2026 · Nürnberg</small></div></header><p class="sheet-rules">'+esc(g.description)+'</p><p>'+entries.length+' Starts in der Gruppe'+(ids.length?' · '+ids.length+' Starter in diesem Pool':'')+'</p>'+(!g.draw?'<p><b>Noch nicht ausgelost</b></p><table><thead><tr><th>Nr.</th><th>Name</th><th>Dojo</th></tr></thead><tbody>'+entries.map((e,i)=>'<tr><td>'+(i+1)+'</td><td>'+esc(entrant(e.id).name)+'</td><td>'+esc(entrant(e.id).dojo)+'</td></tr>').join('')+'</tbody></table>':'')+(rounds.length?'<div class="bracket sheet-bracket">'+rounds.map((r,index)=>'<section class="bracket-round" style="--round:'+index+'"><h3>'+(bs.find(b=>(b.round||0)===r)?.qualification?'Finalqualifikation':(bs.find(b=>(b.round||0)===r)?.roundSize||0)===2&&g.type!==0&&g.type!==2?'Finale / Platz 3':'Runde '+(r+1))+'</h3><div class="round-matches">'+bs.filter(b=>b.kind!=='points'&&(b.round||0)===r).map(b=>'<div class="bracket-bout"><small>Kampf '+num(b)+(b.bronze?' · Platz 3':b.qualification?' · Finalqualifikation':'')+'</small><div class="match-side aka">Aka<br>'+participant(b,'aka')+'</div><div class="match-side shiro">Shiro<br>'+participant(b,'shiro')+'</div><small>'+(b.status==='done'?'Sieger: '+esc(entrant(b.winner).name)+' · '+esc(b.reason):'Ergebnis: __________________')+'</small>'+(admin()&&b.status==='done'?'<button class="quiet small-btn no-print" data-do="reopen-id" data-id="'+b.id+'">Korrigieren</button>':'')+'</div>').join('')+'</div></section>').join('')+'</div>':'')+(points.length?'<h3>Kata · Punkteliste</h3><div class="scroll"><table class="points-sheet"><thead><tr><th>Nr.</th><th>Starter / Dojo</th>'+[1,2,3,4,5,6,7].map(i=>'<th>KR '+i+'</th>').join('')+'<th>Summe</th><th>Platz</th></tr></thead><tbody>'+points.map((b,i)=>'<tr><td>'+(i+1)+'</td><td>'+participant(b,'aka')+'<small>'+esc(b.kata)+'</small></td>'+[0,1,2,3,4,5,6].map(i=>'<td>'+ (b.judges?.[i]===undefined?'':Number(b.judges[i]).toFixed(1))+'</td>').join('')+'<td>'+ (b.judges?.length?((b.judges.reduce((a,x)=>a+x,0)-Math.min(...b.judges)-Math.max(...b.judges))).toFixed(1):'')+'</td><td>'+esc(g.podium?.find(x=>x.entry===b.aka)?.place||'')+'</td></tr>').join('')+'</tbody></table></div><p class="sheet-rules">Eine höchste und eine niedrigste Wertung streichen. Gleichstand: gestrichene niedrigste, dann höchste Wertung, danach Stichkata.</p>':'')+'<footer class="sheet-footer">Hauptkampfrichter: ____________________ &nbsp; Protokoll: ____________________<br>Wettkampfleitung: Martin Daumiller · daumiller@djkb.com</footer></section>';}).join('');}

function clearQueueDrop(){document.querySelectorAll('.queue-drop-before,.queue-drop-after,.queue-drop-valid,.queue-drop-invalid').forEach(el=>el.classList.remove('queue-drop-before','queue-drop-after','queue-drop-valid','queue-drop-invalid'));}
function queueDropAt(e){const lane=e.target.closest('[data-queue-lane]');if(!lane)return null;const card=e.target.closest('[data-queue-job]'),after=!!card&&e.clientY>card.getBoundingClientRect().top+card.getBoundingClientRect().height/2,placement=queuePlacement(S.queue||[],draggedJob,Number(lane.dataset.queueTatami),Number(lane.dataset.queuePhase),card?.dataset.queueJob||null,after);return {lane,card,after,placement};}
async function saveQueueMove(placement,revision){if(queueSaving||placement.noop)return;const current=(S.queue||[]).find(q=>q.id===placement.job);if(!current||current.status==='done'){toast('Dieser Pool ist inzwischen abgeschlossen. Bitte den aktuellen Stand prüfen.');render();return;}const peers=(S.queue||[]).filter(q=>q.phase===current.phase&&q.tatami===current.tatami&&q.status!=='done'),old={job:current.id,tatami:current.tatami,before:peers[peers.findIndex(q=>q.id===current.id)+1]?.id||null};queueSaving=true;render();try{await act({type:'queue',...placement,expectedQueueRevision:revision});queueUndo={...old,afterRevision:S.queueRevision||0};toast(current.group+' · '+poolLabel(current)+' auf Tatami '+placement.tatami+' gespeichert.');}catch(e){toast(e.message);}finally{queueSaving=false;render();}}
async function undoQueueMove(){if(!queueUndo||queueSaving)return;if((S.queueRevision||0)!==queueUndo.afterRevision){toast('Die Poolplanung wurde inzwischen geändert. Bitte den aktuellen Stand prüfen.');return;}const move=queueUndo;queueSaving=true;render();try{await act({type:'queue',job:move.job,tatami:move.tatami,before:move.before,expectedQueueRevision:move.afterRevision});queueUndo=null;toast('Letzte Pool-Verschiebung rückgängig gemacht.');}catch(e){toast(e.message);}finally{queueSaving=false;render();}}
document.addEventListener('pointerdown',e=>{queueDragBlocked=!!e.target.closest('[data-queue-job]')&&!!e.target.closest('button,a,input,select,summary');});
document.addEventListener('dragstart',e=>{const card=e.target.closest('[data-queue-job]');if(!card)return;if(!admin()||!online||queueSaving||queueDragBlocked){e.preventDefault();return;}draggedJob=card.dataset.queueJob;queueDragRevision=S.queueRevision||0;e.dataTransfer.setData('text/plain',draggedJob);e.dataTransfer.effectAllowed='move';card.classList.add('dragging');document.querySelectorAll('.queue-planner').forEach(el=>el.classList.add('queue-drag-active'));});
document.addEventListener('dragover',e=>{if(!draggedJob||!admin()||queueSaving)return;const drop=queueDropAt(e);clearQueueDrop();if(!drop)return;e.preventDefault();if(!drop.placement){e.dataTransfer.dropEffect='none';drop.lane.classList.add('queue-drop-invalid');const message=$('#queue-drag-message');if(message)message.textContent='Bitte innerhalb derselben Wettkampfphase ablegen. Vormittag und Nachmittag bleiben getrennt.';return;}e.dataTransfer.dropEffect='move';drop.lane.classList.add('queue-drop-valid');if(drop.card&&!drop.placement.noop)drop.card.classList.add(drop.after?'queue-drop-after':'queue-drop-before');const source=(S.queue||[]).find(q=>q.id===draggedJob),message=$('#queue-drag-message');if(message)message.textContent=source.group+' → Tatami '+drop.placement.tatami+(drop.placement.before?' · vor '+((S.queue||[]).find(q=>q.id===drop.placement.before)?.group||'dem nächsten Pool'):' · ans Ende dieser Phase');const board=drop.lane.closest('.queue-board'),rect=board.getBoundingClientRect();if(board.scrollWidth>board.clientWidth){if(e.clientX<Math.max(rect.left,0)+40)board.scrollLeft-=16;if(e.clientX>Math.min(rect.right,innerWidth)-40)board.scrollLeft+=16;}});
document.addEventListener('dragleave',e=>{const lane=e.target.closest('[data-queue-lane]');if(lane&&!lane.contains(e.relatedTarget))clearQueueDrop();});
document.addEventListener('drop',async e=>{if(!draggedJob||!admin()||queueSaving)return;e.preventDefault();const drop=queueDropAt(e),revision=queueDragRevision;draggedJob='';clearQueueDrop();document.querySelectorAll('.queue-drag-active').forEach(el=>el.classList.remove('queue-drag-active'));if(!drop?.placement){toast('Pool in einem Bereich derselben Wettkampfphase ablegen.');render();return;}await new Promise(resolve=>setTimeout(resolve,0));await saveQueueMove(drop.placement,revision);});
document.addEventListener('dragend',()=>{draggedJob='';queueDragBlocked=false;clearQueueDrop();document.querySelectorAll('.queue-drag-active').forEach(el=>el.classList.remove('queue-drag-active'));if(!queueSaving)render();});

function personStarts(p){return S.entries.filter(e=>e.active&&(e.personId===p.id||e.kind==='team'&&S.teams.find(t=>t.id===e.personId)?.memberIds?.includes(p.id)));}



function groupDetailsView(){
  if(!admin())return denied();
  const counts=S.overview||[],row=code=>counts.find(x=>x.code===code)||{starts:0,teams:0,people:0,withdrawn:0,dojos:0,tatamis:[],status:'empty'};
  const active=S.groups.filter(g=>g.active),occupied=active.filter(g=>row(g.code).starts),empty=active.filter(g=>!row(g.code).starts);
  const groups=S.groups.filter(g=>{
    const r=row(g.code);return (overviewStatus==='all'||overviewStatus==='inactive'&&!g.active||overviewStatus==='active'&&g.active||overviewStatus==='occupied'&&g.active&&r.starts>0||overviewStatus==='empty'&&g.active&&!r.starts)&&(overviewType===''||g.type===Number(overviewType))&&(!overviewSearch||(g.code+' '+g.description).toLowerCase().includes(overviewSearch.toLowerCase()));
  });
  return '<div class="eyebrow">Wettkampfleitung</div><h1>Gesamtes Wettkampffeld</h1>'+S.groups.filter(g=>g.tie).map(g=>'<div class="note row"><b>Kata-Gleichstand · '+esc(g.code)+'</b><button data-do="tie" data-id="'+esc(g.code)+'">Stichkata werten</button></div>').join('')+'<p class="lead">Alle Gruppen mit aktuellen Starterzahlen. Gruppen auswählen und zusammenlegen oder einzeln bearbeiten und streichen.</p>'+metrics()+'<div class="group-summary"><span><b>'+active.length+'</b> aktive Gruppen</span><span><b>'+occupied.length+'</b> mit Startern</span><span><b>'+empty.length+'</b> leer</span><span><b>'+S.groups.filter(g=>!g.active).length+'</b> gestrichen / zusammengelegt</span></div><div class="bar overview-filters no-print"><label>Gruppen anzeigen<select id="overview-status">'+options([{id:'active',name:'Alle aktiven Gruppen'},{id:'occupied',name:'Nur mit Startern'},{id:'empty',name:'Nur leere Gruppen'},{id:'inactive',name:'Gestrichen / zusammengelegt'},{id:'all',name:'Alle Gruppen einschließlich Historie'}],overviewStatus)+'</select></label><label>Disziplin<select id="overview-type"><option value="">Alle Disziplinen</option>'+competitionTypes.map((n,i)=>'<option value="'+i+'" '+(overviewType===String(i)?'selected':'')+'>'+n+'</option>').join('')+'</select></label><label>Gruppe suchen<input id="overview-search" value="'+esc(overviewSearch)+'" placeholder="Kennung, Alter oder Beschreibung"></label></div><div class="bar no-print"><p>'+groups.length+' Gruppen in dieser Ansicht · '+selectedGroups.size+' ausgewählt</p><div class="actions"><button data-do="mergeSelection" '+(selectedGroups.size<2?'disabled':'')+'>Auswahl zusammenlegen</button><button class="quiet" data-do="drawAll">Offene Gruppen auslosen</button><a class="btn quiet" href="#printing">Mehrere Listen drucken</a></div></div><div class="card scroll group-overview"><table><thead><tr><th class="no-print">Auswahl</th><th>Gruppe / Regeln</th><th>Starter / Teams</th><th>Dojos</th><th>Pools / Tatamis</th><th>Status</th><th class="no-print">Aktionen</th></tr></thead><tbody>'+groups.map(g=>{
    const r=row(g.code),editable=g.active&&!r.started;
    return '<tr class="'+(!g.active?'inactive-group':'')+'"><td class="no-print"><input type="checkbox" aria-label="Gruppe '+esc(g.code)+' auswählen" data-group-select="'+esc(g.code)+'" '+(selectedGroups.has(g.code)?'checked':'')+' '+(!editable?'disabled':'')+'></td><td><b>'+esc(g.code)+'</b>'+beltStrip(r.belts)+'<small>'+competitionTypes[g.type]+' · '+groupAge(g)+' · '+esc({m:'männlich',w:'weiblich',x:'mixed'}[g.gender]||'mixed')+' · '+groupGrade(g)+'</small><details><summary>Regeln</summary><p>'+esc(g.description)+'</p></details></td><td class="group-count"><strong>'+r.starts+'</strong><small>'+ (g.type>=2?'Teams · '+(r.teams*3)+' Startplätze':'Personen')+'</small>'+(r.pendingTeams?'<small class="warning-text">'+r.pendingTeams+' Teams ungeprüft</small>':'')+(r.withdrawn?'<small>'+r.withdrawn+' zurückgezogen</small>':'')+'</td><td>'+r.dojos+'</td><td>'+(g.active?g.pools+' '+(g.pools===1?'Pool':'Pools')+'<small>'+ (r.tatamis.length?r.tatamis:[g.tatami]).map(t=>'Tatami '+t).join(' / ')+'</small>':'–')+'</td><td><span class="pill '+(r.status==='live'?'live':'')+'">'+statusLabels[r.status]+'</span>'+(groupChange(g)?'<small class="group-change">'+esc(groupChange(g))+'</small>':'')+'</td><td class="no-print"><div class="actions"><button class="quiet small-btn" data-do="groupStarters" data-id="'+esc(g.code)+'">Starter</button>'+(editable&&r.starts?'<button class="small-btn" data-do="draw" data-id="'+esc(g.code)+'">'+(g.draw?'Pools / neu auslosen':'Auslosen')+'</button>':'')+(editable?'<button class="quiet small-btn" data-do="group" data-id="'+esc(g.code)+'">Einstellungen</button><button class="quiet small-btn" data-do="groupMerge" data-id="'+esc(g.code)+'">Zusammenlegen</button><button class="danger small-btn" data-do="groupStatus" data-id="'+esc(g.code)+'">Streichen</button>':!g.active&&!g.mergedInto?'<button class="quiet small-btn" data-do="groupStatus" data-id="'+esc(g.code)+'">Wieder aktivieren</button>':r.started?'<button class="quiet small-btn" data-do="restructure">Restwettbewerb neu aufsetzen</button>':'')+'</div></td></tr>';
  }).join('')+'</tbody></table>'+(!groups.length?'<p>Keine Gruppen in dieser Auswahl.</p>':'')+'</div><p class="muted">Personen können in Kata und Kumite starten; die Gesamtzahl der Einzelstarts ist daher höher als die Zahl der erfassten Personen. Bei Teams zählen die drei Plätze als ein Teamstart. Änderungen nach Wettkampfbeginn erfolgen über den Restwettbewerb.</p>';
}

function showMergeDialog(id='',selection=[],preset={}){
  const selected=selection.map(code=>group(code)).filter(Boolean),target=group(id)||selected[0];
  if(!target)throw Error('Mindestens zwei Gruppen auswählen');
  if(selected.some(g=>g.type!==target.type))throw Error('Nur Gruppen derselben Disziplin zusammenlegen');
  const available=S.groups.filter(g=>g.active&&g.type===target.type&&!S.overview?.find(r=>r.code===g.code)?.started);
  if(!available.some(g=>g.code===target.code))throw Error('Begonnene Gruppe über den Restwettbewerb bearbeiten');
  if(available.length<2)throw Error('Keine zweite unbegonnene Gruppe dieser Disziplin verfügbar');
  const phasesForType=target.type===0?[1,3]:target.type===1?[2,4]:target.type===2?[0,3]:[6];
  form('Gruppen zusammenlegen','<div id="merge-form-fields"><p>Die Zielkennung bleibt erhalten. Die anderen Gruppen werden als zusammengelegt dokumentiert. Vorhandene unbegonnene Auslosungen werden aufgehoben; anschließend neu auslosen.</p>'+select('group','Zielgruppe',options(available,target.code,'code','code'))+'<fieldset class="merge-options"><legend>Weitere Gruppen</legend>'+available.map(g=>'<label><input type="checkbox" name="merge_'+esc(g.code)+'" '+(selection.includes(g.code)?'checked':'')+'>'+esc(g.code)+' · '+groupAge(g)+' · '+(S.overview?.find(r=>r.code===g.code)?.starts||0)+' Starts</label>').join('')+'</fieldset><p id="merge-preview" class="note"></p>'+select('phase','Wettkampfphase',phasesForType.map(i=>'<option value="'+i+'">'+esc(phases[i])+'</option>').join(''))+'<label>Gemeinsame Bezeichnung und geltende Regeln<textarea name="description" required>'+esc(target.description)+'</textarea></label><label>Begründung<textarea name="reason" required></textarea></label></div>',async f=>{
    const sources=Object.keys(f).filter(k=>k.startsWith('merge_')).map(k=>k.slice(6)).filter(code=>code!==f.group);
    const result=await act({type:'mergeGroups',group:f.group,sources,phase:Number(f.phase),description:f.description,reason:f.reason,confirmProgramChange:!!f.confirmProgramChange});selectedGroups.clear();toast(result.starts+' Starts in '+result.group+' zusammengeführt. Neu auslosen.');
  });
  if(preset.description)$('#form textarea[name=description]').value=preset.description;
  const approval=document.createElement('label');approval.className='check';approval.innerHTML='<input type="checkbox" name="confirmProgramChange">Änderungen von Wertung, Alter, Graduierung und Programm sind mit den betroffenen Coaches abgestimmt.';$('#merge-form-fields').append(approval);
  $('#form button[type=submit]').textContent='Zusammenlegung durchführen';updateMergePreview();
}

function updateMergePreview(){
  if(!$('#merge-form-fields'))return;
  const target=$('#form select[name=group]').value,codes=[...new Set([target,...Array.from($('#form').querySelectorAll('input[name^="merge_"]:checked')).map(x=>x.name.slice(6))])];
  const input=$('#form textarea[name=description]');let p=combinationPreview(S,codes,input.value);
  if(p.mixed&&!/mixed/i.test(input.value))input.value=input.value.replace(/weiblich|maennlich|männlich/gi,'Mixed');
  p=combinationPreview(S,codes,input.value);
  const type=group(target).type,phase=type===0?(p.maxAge<=12?1:3):type===1?(p.maxAge<=12?2:4):type===2?(p.maxAge<=11?0:3):6;
  const phaseInput=$('#form select[name=phase]');if(!phaseInput.dataset.manual)phaseInput.value=String(phase);
  const age=p.maxAge>=99?'ab '+p.minAge+' Jahren':p.minAge+'–'+p.maxAge+' Jahre',grade=p.maxKyu===0?'ab '+p.minKyu+'. Kyu':p.minKyu===p.maxKyu?p.minKyu+'. Kyu':p.minKyu+'.–'+p.maxKyu+'. Kyu';
  $('#merge-preview').textContent=codes.join(' + ')+' · '+p.counts.join(' + ')+' = '+p.total+' aktive Starts → '+target+' · '+age+' · '+grade+' · '+(p.mixed?'Mixed weiblich / männlich':'gemeinsame Wertung')+' · '+programName(p.program)+(p.programChange?' · Kampfform / Programm wird geändert':'')+(!p.mixedAllowed?' · Mixed nur für Kata oder Kihon-Ippon möglich. Gemeinsame Regeln ändern.':'')+'. Unbegonnene Auslosungen dieser Gruppen werden aufgehoben; Gebühren und ursprüngliche Meldungen bleiben erhalten.';
  const confirm=$('#form input[name=confirmProgramChange]');confirm.required=p.mixed||p.programChange;
  const unavailable=codes.length<2||!p.mixedAllowed;$('#form button[type=submit]').dataset.unavailable=unavailable?'1':'0';$('#form button[type=submit]').disabled=unavailable;
}
document.addEventListener('input',e=>{if(e.target.name==='description'&&e.target.closest('#merge-form-fields'))updateMergePreview();});

function showGroupStatusDialog(code){
  const g=group(code),r=S.overview?.find(r=>r.code===code),restore=!g.active;
  form((restore?'Gruppe wieder aktivieren · ':'Gruppe streichen · ')+code,
    restore?'<p>Die Gruppe wird wieder verfügbar. Früher zurückgezogene Starts bleiben zurückgezogen und müssen bei Bedarf neu hinzugefügt werden.</p><label>Begründung<textarea name="reason" required></textarea></label>':
    '<p><b>'+Number(r?.starts||0)+' aktive Starts</b> in '+esc(code)+'. Die Gruppe wird aus Zeitplan und aktuellen Gebühren entfernt. Die ursprünglichen Meldungen und das Änderungsprotokoll bleiben erhalten.</p>'+(r?.starts?'<label><input type="checkbox" name="withdraw" required>Alle '+r.starts+' Starts dieser Gruppe zurückziehen und die unbegonnene Auslosung aufheben</label>':'')+'<p class="note">Wenn die Starter weiter teilnehmen sollen, die Gruppe stattdessen zusammenlegen.</p><label>Begründung<textarea name="reason" required></textarea></label>',
    async f=>{const result=await act({type:'groupStatus',group:code,active:restore,withdraw:!!f.withdraw,reason:f.reason});selectedGroups.clear();return result;});
  $('#form button[type=submit]').textContent=restore?'Wieder aktivieren':'Gruppe streichen';
}

function feesView(){
  if(!admin()||!S.fees)return denied();const f=S.fees;
  return '<div class="eyebrow">Privat · Martin Daumiller / Besitzerkonto</div><h1>Startgebühren je Dojo</h1><div class="metrics fees-metrics">'+metric(money(f.totalCents),'Aktuelle Gesamtsumme')+metric(f.individualStarts,'Einzelstarts × '+money(f.rates.individualCents))+metric(f.teamStarts,'Teamstarts × '+money(f.rates.teamCents))+metric(f.rows.length,'Dojos')+'</div><p class="lead">Berechnung aus den aktuell aktiven Starts. Manuell ergänzte Starts zählen mit; zurückgezogene Starts und gestrichene Gruppen sind nicht enthalten.</p><div class="bar no-print"><p class="muted">Sichtbar nur mit deinem Leitungszugang oder dem Besitzerkonto.</p><div class="actions"><button class="quiet" data-do="feesCsv">CSV herunterladen</button><button class="quiet" data-practical-action="printOne" data-group="'+esc(g.code)+'"'+(reportPool!==''?' data-pool="'+esc(reportPool)+'"':'')+'>A4-PDF</button>'+(admin()?'<button class="quiet" data-practical-action="obmannOne" data-group="'+esc(g.code)+'">Obmann-Protokoll</button>':'')+'<a class="btn quiet" href="#printing">Mehrere Listen drucken</a></div></div><div class="card scroll"><table class="fees-table"><thead><tr><th>Dojo</th><th>Einzelstarts</th><th>Teams</th><th>Einzelgebühren</th><th>Teamgebühren</th><th>Summe</th><th class="no-print"></th></tr></thead><tbody>'+f.rows.map(r=>'<tr><td><b>'+esc(r.dojo)+'</b>'+(r.withdrawn?'<small>'+r.withdrawn+' zurückgezogene Starts</small>':'')+'</td><td>'+r.individualStarts+'</td><td>'+r.teamStarts+'</td><td>'+money(r.individualCents)+'</td><td>'+money(r.teamCents)+'</td><td><b>'+money(r.totalCents)+'</b></td><td class="no-print"><button class="quiet small-btn" data-do="feesDetails" data-id="'+esc(r.dojo)+'">Meldungen / Details</button></td></tr>').join('')+'</tbody><tfoot><tr><th>Gesamt</th><th>'+f.individualStarts+'</th><th>'+f.teamStarts+'</th><th>'+money(f.rows.reduce((n,r)=>n+r.individualCents,0))+'</th><th>'+money(f.rows.reduce((n,r)=>n+r.teamCents,0))+'</th><th>'+money(f.totalCents)+'</th><th class="no-print"></th></tr></tfoot></table></div><p class="note">Die ursprünglichen Gebührenangaben stehen unter „Meldungen / Details“. Mehrere Meldungen werden als Historie angezeigt und nicht ungeprüft summiert. Die aktuelle Berechnung ist keine Zahlungseingangsliste.</p>';
}

function showFeesDetails(dojo){
  if(!S.fees)throw Error('Nur eigener Leitungszugang / Besitzerkonto');const r=S.fees.rows.find(r=>r.dojo===dojo);if(!r)throw Error('Dojo fehlt');pendingForm=null;
  dialog.innerHTML='<button class="close" data-do="close" aria-label="Schließen">×</button><h2>'+esc(dojo)+'</h2><p><b>Aktuell: '+money(r.totalCents)+'</b> · '+r.individualStarts+' Einzelstarts / '+r.teamStarts+' Teams</p><h3>Aktive Gruppen</h3>'+r.groups.map(g=>'<p>'+esc(g.code)+' · '+g.starts+' Starts</p>').join('')+'<h3>Ursprüngliche Meldeangaben</h3><div class="scroll"><table><thead><tr><th>Eingang</th><th>Einzel / Teams</th><th>Gebühr gemeldet</th><th>Aus Meldung berechnet</th></tr></thead><tbody>'+r.imports.map(i=>'<tr><td>'+esc(i.received?new Date(i.received).toLocaleString('de-DE'):'Manuell / ohne Eingangszeit')+'</td><td>'+i.individualStarts+' / '+i.teamStarts+'</td><td>'+(i.declaredCents===null?'Nicht angegeben':money(i.declaredCents))+'</td><td>'+(i.calculatedCents===null?'–':money(i.calculatedCents))+'</td></tr>').join('')+'</tbody></table></div>'+(!r.imports.length?'<p>Keine ursprüngliche Meldung hinterlegt.</p>':'')+'<p class="muted">Diese Historie bleibt auch bei späteren Korrekturen erhalten.</p><button data-do="close">Schließen</button>';dialog.showModal();
}

function exportFeesCsv(){
  if(!S.fees)throw Error('Nur eigener Leitungszugang / Besitzerkonto');
  const cell=x=>'"'+String(x??'').replace(/^[=+\-@]/,"'"+'$&').replace(/"/g,'""')+'"',amount=n=>(n/100).toFixed(2).replace('.',',');
  const rows=[['Dojo','Einzelstarts','Teamstarts','Einzelgebuehren EUR','Teamgebuehren EUR','Summe EUR'],...S.fees.rows.map(r=>[r.dojo,r.individualStarts,r.teamStarts,amount(r.individualCents),amount(r.teamCents),amount(r.totalCents)]),['Gesamt',S.fees.individualStarts,S.fees.teamStarts,amount(S.fees.rows.reduce((n,r)=>n+r.individualCents,0)),amount(S.fees.rows.reduce((n,r)=>n+r.teamCents,0)),amount(S.fees.totalCents)]];
  const url=URL.createObjectURL(new Blob(['\ufeff'+rows.map(r=>r.map(cell).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'}));
  const a=document.createElement('a');a.href=url;a.download='SDM2026-Startgebuehren-'+new Date().toISOString().slice(0,10)+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);
}

function workspaceURL(practice,username=S.user?.name){const u=new URL(location.href);u.searchParams.set('v','50');if(practice)u.searchParams.set('practice','1');else u.searchParams.delete('practice');if(username)u.searchParams.set('zugang',username);u.hash=practice?'rehearsal':'manage';return u.href;}
function rehearsalView(){if(S.testRoom)return sharedTestView();if(!admin()&&!table())return denied();return '<h1>Testen und üben</h1>'+training.card()+'<section class="card"><h2>Tutorial für die Tischbesatzung</h2><p>Jede Disziplin Schritt für Schritt am echten Übungstisch durchgehen.</p><a class="btn" href="#tutorial">Tutorial starten</a></section>'+sharingCard()+'<p class="lead">Alle fünf Tische üben mit fiktiven Startern. Die Leitung und Tischbesatzungen benutzen ihre normalen Zugänge.</p>'+(S.practice?'<div class="actions">'+(admin()?'<button data-write data-do="rehearsalReset">'+(S.practiceReady?'Testlauf neu beginnen':'Testlauf vorbereiten')+'</button>':'')+(S.practiceReady?'<a class="btn" href="#desk">Zum eigenen Tisch</a>':'<p>Die Leitung muss den Testlauf zuerst vorbereiten.</p>')+'</div>':'<a class="btn" href="'+esc(workspaceURL(true))+'">Testlauf öffnen</a>')+'<ol><li>Leitung: Testlauf öffnen und vorbereiten. Es entstehen Teststarter für Kata und Kumite auf fünf Tatamis.</li><li>Jede Tischbesatzung öffnet den passenden Link und meldet sich an.</li><li>Aufnahmezeit auf 00:00:00 setzen. Begegnung starten, Wertung erfassen und Ergebnis abschließen. Über „Nächste Begegnung anzeigen“ bis zum Finale fortfahren.</li><li>Eine zusätzliche Zeitmarke setzen. Die Leitung prüft die Zeitmarken und Ergebnisse.</li><li>Verbindung kurz unterbrechen und wiederherstellen. Der gespeicherte Stand muss wieder erscheinen.</li><li>Zum Wettkampf zurückkehren. Übungsergebnisse bleiben im Testlauf.</li></ol><div class="card"><h2>Links für die Tische</h2>'+[1,2,3,4,5].map(i=>'<p><a href="'+esc(workspaceURL(true,'tatami'+i))+'">Testlauf Tatami '+i+'</a></p>').join('')+'</div>';
}
function parseClock(value){if(!/^\d{1,3}:[0-5]\d:[0-5]\d$/.test(value))throw Error('Zeit als HH:MM:SS eingeben');const [h,m,s]=value.split(':').map(Number);return h*3600+m*60+s;}
function clockText(seconds){if(seconds===null||seconds===undefined)return 'Aufnahmezeit fehlt';return [Math.floor(seconds/3600),Math.floor(seconds/60)%60,seconds%60].map(x=>String(x).padStart(2,'0')).join(':');}
function streamControls(t,b){const r=(S.recordings||[]).find(r=>r.id===t.recordingId);return '<details class="card"><summary>Video-Zuordnung · optional</summary><p>Start und Ergebnis erhalten automatisch Zeitmarken. Nur für das spätere Wiederfinden im Video einmal die Aufnahmezeit abgleichen.</p><div class="actions"><button data-write class="quiet" data-do="streamClock" data-tatami="'+t.id+'">'+(r?'Aufnahmezeit korrigieren':'Aufnahmezeit abgleichen')+'</button><a class="btn quiet" href="#timestamps">Zeitmarken ansehen</a></div></details>'; }
function timestampsView(){if(!S.user&&!S.event.published)return denied();const labels={start:'Begegnung gestartet',finish:'Begegnung beendet',manual:'Tischmarke','team-start':'Einzelkampf gestartet','team-finish':'Einzelkampf beendet',correction:'Korrektur'};return '<h1>Stream-Zeitmarken</h1><p class="lead">Zeitpositionen beziehen sich auf die am Tisch abgeglichene Aufnahme. Uhrzeit und Starter bleiben auch ohne eingerichtete Aufnahme erhalten.</p>'+(S.user?'<button class="quiet" data-do="markersCsv">Zeitmarken als CSV</button>':'')+'<div class="card scroll"><table><thead><tr><th>Aufnahmezeit</th><th>Uhrzeit</th><th>Tatami / Gruppe</th><th>Starter</th><th>Ereignis</th></tr></thead><tbody>'+(S.streamMarkers||[]).slice().reverse().map(m=>'<tr><td>'+(m.url?'<a href="'+esc(m.url)+'" target="_blank" rel="noopener">'+clockText(m.seconds)+'</a>':clockText(m.seconds))+'</td><td>'+esc(new Date(m.at).toLocaleTimeString('de-DE'))+'</td><td>'+m.tatami+' · '+esc(m.group)+(m.individual?'<small>Team-Einzelkampf '+m.individual+'</small>':'')+'</td><td>'+(m.shiro?'Aka: '+esc(m.aka)+'<small>Shiro: '+esc(m.shiro)+'</small>':'Starter: '+esc(m.aka))+'</td><td>'+esc(labels[m.kind]||m.kind)+'<small>'+esc(m.note||'')+'</small></td></tr>').join('')+'</tbody></table>'+(!(S.streamMarkers||[]).length?'<p>Noch keine Zeitmarken.</p>':'')+'</div>';}
function download(name,text,type){const u=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function markersCsv(){const rows=[['Aufnahmezeit','Uhrzeit UTC','Tatami','Gruppe','Aka','Shiro','Ereignis','Notiz','Video'],...(S.streamMarkers||[]).map(m=>[clockText(m.seconds),m.at,m.tatami,m.group,m.aka,m.shiro,m.kind,m.note||'',m.url||''])];return '\uFEFF'+rows.map(r=>r.map(v=>'"'+String(v??'').replace(/^[=+@-]/,"'").replaceAll('"','""')+'"').join(';')).join('\r\n');}
function emergencyView(){if(!admin())return denied();if(!S.fees)return networkUI.view();return networkUI.view()+'<h1>Excel-Notfallmappe</h1><p class="lead">Die Mappe enthält eine Gruppeneinteilung mit Startern, Dojos, Startnummern, Pools und Tatamis sowie Begegnungen, Kata-Wertungen, Mannschaftskämpfe und Startgebühren. Gelbe Felder sind für manuelle Ergebnisse vorgesehen.</p><p>Bei einem Ausfall: Mappe herunterladen, unter neuem Namen speichern und auf dem Blatt „Weiterarbeiten“ beginnen. Sieger und Wertungen in den Begegnungen eintragen. Folgebegegnungen übernehmen die Sieger bzw. Verlierer.</p><div class="actions"><button data-write data-do="backupNow">Mappe jetzt aktualisieren</button><a class="btn" href="./notfall.php?download=1">Excel vom Server herunterladen</a><a class="btn quiet" href="./notfall.php?download=1&amp;format=obmann">Gespeicherte Obmann-PDF</a><a class="btn quiet" href="./notfall.php?download=1&amp;format=lists">Gespeicherte Hallenlisten</a><a class="btn quiet" href="#printing">Aktuelle Listen / Sieger-Excel</a><a class="btn quiet" href="./notfall.php?independent=1" target="_blank">Unabhängiger Notfallzugang</a></div><p id="backup-status" class="note">Der Server zeigt im Notfallzugang den gespeicherten Stand. Vor dem Wettkampfbeginn eine lokale Kopie herunterladen.</p><p>Solange dein Leitungsbereich geöffnet ist, wird die Mappe nach Änderungen automatisch auf dem Server aktualisiert. Der Notfallzugang akzeptiert deinen Leitungsnamen und dein Passwort auch bei ausgefallenem Wettkampfzentrum.</p>';}
let backupRevision=-1,backupBusy=false;
async function updateEmergency(force=false){if(!admin()||!S.fees||S.practice||backupBusy||backupRevision===S.revision||location.hostname!== 'karate-klub-ippon.de')return;backupBusy=true;try{const r=await fetch(resourceURL('notfall.php?action=refresh'+(force?'&force=1':'')),{method:'POST',headers:{'X-CSRF-Token':S.csrf}}),data=await r.json();if(!r.ok)throw Error(data.error||'Notfallmappe nicht aktualisiert');backupRevision=data.revision;const el=$('#backup-status');if(el)el.textContent='Auf dem Server gespeichert · Stand '+data.revision+' · '+new Date(data.at).toLocaleString('de-DE');}catch(e){const el=$('#backup-status');if(el)el.textContent=e.message+' · gespeicherte Mappe im Notfallzugang prüfen.';}finally{backupBusy=false;}}
setInterval(()=>{if(S?.network?.background!==false)updateEmergency();},10000);

function cadreBadge(e){return admin()&&e?.cadre?'<span class="pill cadre-pill">Kader'+(e.seed?' · gesetzt '+e.seed:'')+'</span>':admin()&&e?.seed?'<span class="pill">Gesetzt '+e.seed+'</span>':'';}
function seedingNotice(g){if(!admin()||!g.draw)return '';const c={...g.draw.constraints,cadrePairings:(S.bouts||[]).filter(b=>b.group===g.code&&b.kind==='match'&&!(b.round||0)&&b.aka&&b.shiro&&entrant(b.aka).cadre&&entrant(b.shiro).cadre).length};return (g.draw.seedingStale?'<p class="note">Kader / Setzung geändert. Die bisherige Auslosung bleibt sichtbar. <button class="quiet small-btn" data-do="draw" data-id="'+esc(g.code)+'">Neu auslosen</button></p>':'')+(c?.cadrePairings?'<p class="note">'+c.cadrePairings+' Kaderbegegnung'+(c.cadrePairings===1?'':'en')+' in der ersten Runde. Bei vielen Kaderathleten oder festen Setzungen können solche Begegnungen entstehen. Auslosung prüfen.</p>':'');}
function listGroupMats(g,bs){const planned=(S.queue||[]).filter(q=>q.group===g.code).map(q=>q.tatami);if(!bs.length&&planned.length)return [...new Set(planned)].sort();if(bs.length)return [...new Set(bs.map(mat))].sort();if(g.pools>1)return [...new Set(Array.from({length:g.pools},(_,i)=>g.poolTatamis?.[i]||((g.tatami+i-1)%5+1)))].sort();return [g.tatami];}
function listParticipant(b,side,all){const id=b[side];if(id){const e=entrant(id);return '<strong>'+esc(e.name)+'</strong><small>'+(e.startNumber?'Start '+e.startNumber+' · ':'')+esc(e.dojo)+'</small>'+cadreBadge(e);}const src=b.sources?.[side==='aka'?0:1];return '<span class="muted">'+(src?(b.fromLoser?'Verlierer':'Sieger')+' aus Begegnung '+(all.findIndex(x=>x.id===src)+1):b.kind==='points'?'Noch offen':'Freilos')+'</span>';}
function pairingRow(b,all){const n=all.findIndex(x=>x.id===b.id)+1,m=mode(group(b.group),b),label=b.bronze?'Platz 3':b.final?'Finale':b.kind==='points'?'Kata-Punkte':(b.round?'Runde '+(b.round+1):'Vorrunde');return '<article class="pairing-row" data-bout-id="'+esc(b.id)+'"><div class="pairing-heading"><b>Begegnung '+n+'</b><span>'+esc(label)+'</span><span class="pill mat-label">Tatami '+mat(b)+(b.pool?' · Pool '+b.pool:'')+'</span><span class="pill '+(b.status==='live'?'live':'')+'">'+esc({ready:'Bereit',live:'Läuft',done:b.reason==='Freilos'?'Freilos':'Beendet',waiting:'Folgerunde'}[b.status]||b.status)+'</span></div>'+(b.kind==='points'?'<div class="pairing-solo"><small>Kata-Auftritt</small>'+listParticipant(b,'aka',all)+'</div>':'<div class="pairing-sides"><div class="pairing-side aka"><span>🔴 Aka</span>'+listParticipant(b,'aka',all)+'</div><b class="pairing-vs">gegen</b><div class="pairing-side shiro"><span>⚪ Shiro</span>'+listParticipant(b,'shiro',all)+'</div></div>')+(b.status==='done'&&b.reason!=='Freilos'?'<p class="pairing-result">'+(b.kind==='points'&&b.judges?.length?'Wertung: '+(b.judges.reduce((n,x)=>n+x,0)-Math.min(...b.judges)-Math.max(...b.judges)).toFixed(1):b.winner?'Sieger: '+esc(entrant(b.winner).name):'Kein Sieger')+'</p>':'')+((admin()||table())&&['ready','live'].includes(b.status)?'<button class="quiet small-btn no-print" data-do="openListBout" data-id="'+esc(b.id)+'">Am Tisch anzeigen</button>':'')+'</article>';}
function starterListsView(){
 const es=S.entries||[],chosenMat=table()?S.user.tatami:listMat,allGroups=S.groups.filter(g=>g.active&&es.some(e=>e.active&&e.group===g.code)),match=e=>(!dojoFilter||entrant(e.id).dojo===dojoFilter)&&(!query||[entrant(e.id).name,entrant(e.id).dojo,e.group].some(x=>String(x).toLowerCase().includes(query.toLowerCase())));
 const shown=allGroups.filter(g=>(!selectedGroup||g.code===selectedGroup)&&es.some(e=>e.group===g.code&&match(e))&&(!chosenMat||listGroupMats(g,S.bouts.filter(b=>b.group===g.code)).includes(chosenMat)));
 const toolbar='<div class="bar no-print"><input id="search" class="search" placeholder="Starter, Dojo oder Gruppe suchen" value="'+esc(query)+'"><div class="actions"><select id="group-filter" aria-label="Gruppe"><option value="">Alle belegten Gruppen</option>'+options(allGroups,selectedGroup,'code',g=>g.code+' · '+S.entries.filter(e=>e.active&&e.group===g.code).length+' '+(g.type>=2?'Teams':'Starter')+' · '+competitionTypes[g.type])+'</select><select id="dojo-filter" aria-label="Dojo"><option value="">Alle Dojos</option>'+options([...new Set(es.map(e=>entrant(e.id).dojo))].sort().map(name=>({name})),dojoFilter,'name','name')+'</select><button class="quiet" data-do="print">Drucken</button></div></div><div class="list-switch no-print">'+(table()?'<span class="pill mat-label">Tatami '+S.user.tatami+'</span>':[[0,'Alle Tatamis'],...[1,2,3,4,5].map(n=>[n,'Tatami '+n])].map(([n,l])=>'<button class="'+(chosenMat===n?'':'quiet')+'" data-do="listMat" data-id="'+n+'" aria-pressed="'+(chosenMat===n)+'">'+l+'</button>').join(''))+'<span class="list-switch-spacer"></span>'+[['pairings','Wer gegen wen'],['people','Personenliste']].map(([id,l])=>'<button class="'+(listMode===id?'':'quiet')+'" data-do="listMode" data-id="'+id+'" aria-pressed="'+(listMode===id)+'">'+l+'</button>').join('')+'</div>';
 let html='<div class="eyebrow">Gruppen · Pools · Tatamis</div><h1>Starterlisten und Begegnungen</h1>'+(admin()?'<div class="actions no-print"><a class="btn quiet" href="#cadre">Kader / Setzung festlegen</a><button class="quiet" data-do="drawAll">Offene Gruppen auslosen</button></div>':'')+toolbar;
 if(!S.user&&!S.event.published)return html+'<p class="note">Die Leitung hat die Starterlisten noch nicht öffentlich freigegeben.</p>';
 if(listMode==='people'){const codes=new Set(shown.map(g=>g.code)),entries=es.filter(e=>codes.has(e.group)&&match(e));return html+'<div class="card scroll"><table><thead><tr><th>Gruppe</th><th>Tatami / Pool</th><th>Startnummer</th><th>Starter</th><th>Dojo</th><th>Gegner / Auftritt</th></tr></thead><tbody>'+entries.map(e=>{const g=group(e.group),r=entryRoute(e),b=S.bouts.find(b=>b.status!=='done'&&(b.aka===e.id||b.shiro===e.id))||S.bouts.find(b=>b.aka===e.id||b.shiro===e.id),other=b&&(b.aka===e.id?b.shiro:b.aka),slot=g.draw?.slots?.indexOf(e.id),number=slot>=0?slot+1:e.startNumber;return '<tr class="'+(!e.active?'withdrawn':'')+'"><td><button class="quiet small-btn" data-do="listGroup" data-id="'+esc(e.group)+'">'+esc(e.group)+'</button></td><td><b>Tatami '+r.tatami+'</b><small>'+ (r.pool?'Pool '+r.pool:g.draw||g.drawn?'Finale / direkt':'Noch nicht ausgelost')+'</small></td><td>'+(number||'–')+'</td><td><b>'+esc(entrant(e.id).name)+'</b>'+cadreBadge(entrant(e.id))+'</td><td>'+esc(entrant(e.id).dojo)+'</td><td>'+esc(b?.kind==='points'?'Kata-Auftritt':other?entrant(other).name:b?'Freilos / Folgerunde':'Auslosung offen')+'</td></tr>';}).join('')+'</tbody></table></div>';}
 return html+shown.map(g=>{const all=S.bouts.filter(b=>b.group===g.code),bs=all.filter(b=>!chosenMat||mat(b)===chosenMat),mats=listGroupMats(g,bs),entries=es.filter(e=>e.group===g.code&&e.active),first=bs.filter(b=>(b.round||0)===0&&!b.bronze),later=bs.filter(b=>!first.includes(b));return '<section class="starter-group" data-pair-group="'+esc(g.code)+'"><div class="starter-group-head"><div><h2>'+esc(g.code)+'<small>'+esc(competitionTypes[g.type])+' · '+entries.length+' Starts</small></h2></div><div class="actions">'+mats.map(t=>'<span class="pill mat-label">Tatami '+t+'</span>').join('')+'<button class="quiet small-btn" data-do="bracket" data-id="'+esc(g.code)+'">Wettkampfbaum / Druckliste</button>'+ (admin()&&!all.some(b=>b.started)?'<button class="small-btn" data-do="draw" data-id="'+esc(g.code)+'">'+(g.draw?'Pools / neu auslosen':'Auslosen')+'</button>':'')+'</div></div><p class="muted group-rule-short">'+esc(g.description)+'</p>'+seedingNotice(g)+(!bs.length?'<p class="note">'+(g.draw||g.drawn?'Für diese Auswahl sind keine Begegnungen sichtbar.':'Noch nicht ausgelost. Erst nach der Auslosung stehen die Gegner fest.')+'</p><div class="starter-roster">'+entries.map(e=>'<div><b>'+esc(entrant(e.id).name)+'</b><small>'+esc(entrant(e.id).dojo)+'</small>'+cadreBadge(entrant(e.id))+'</div>').join('')+'</div>':first.map(b=>pairingRow(b,all)).join('')+(later.length?'<details class="later-rounds" '+(later.some(b=>['ready','live'].includes(b.status))?'open':'')+'><summary>Weitere Runden, Finale und Platz 3 · '+later.length+' Begegnungen</summary>'+later.map(b=>pairingRow(b,all)).join('')+'</details>':''))+'</section>';}).join('')+(!shown.length?'<p class="note">Keine Gruppen in dieser Auswahl.</p>':'');
}
function editCadre(el){cadreUI.edit(el);}
async function saveCadre(){await cadreUI.save();}
function registrationCard(){return '<section class="card registration-card"><h2>Meldungen aktuell halten</h2><p>Neue Meldungen abrufen, Änderungen prüfen und ausgewählte Starter oder Teams übernehmen.</p><div class="actions"><a class="btn" href="#registrations">Meldungen prüfen / hinzufügen</a>'+(S.mailConfigured?'<button class="quiet" data-write data-do="registrationMail">Auf neue Meldungen prüfen</button>':'')+'</div></section>';}
function registrationRows(r){const order={blocked:0,review:1,new:2,update:3,unchanged:4},open=r.items.filter(i=>i.status!=='unchanged');return r.items.filter(i=>(registrationFilter==='all'||registrationFilter==='open'&&(!open.length||i.status!=='unchanged')||registrationFilter==='unchanged'&&i.status==='unchanged')&&(!registrationQuery||(i.label+' '+i.dojo).toLocaleLowerCase('de').includes(registrationQuery.toLocaleLowerCase('de')))).sort((a,b)=>order[a.status]-order[b.status]);}
function registrationsView(){
 if(!admin())return denied();if(S.practice&&!S.testRoom)return '<h1>Meldungen</h1><p>Im gemeinsamen Tisch-Test sind echte Importe gesperrt. Über einen Feedback-Testlink kannst du Beispielmeldungen ausprobieren.</p><a class="btn" href="#rehearsal">Zum Testlauf</a>';
 const r=registrationPreview,selected=r?.items.filter(i=>registrationSelection.has(i.id))||[],affected=[...new Set(selected.flatMap(i=>[...i.affected,...(registrationConflicts.has(i.id)?i.conflictAffected||[]:[])]))],labels={new:'Neu',update:'Änderung',unchanged:'Bereits vorhanden',review:'Manuelle Änderung prüfen',blocked:'Bitte korrigieren'};
 return '<div class="eyebrow">Wettkampfleitung</div><h1>Meldungen prüfen und aktualisieren</h1><p class="lead">Neue Meldungen prüfen, Angaben direkt korrigieren und die gewünschte Auswahl übernehmen.</p><div class="card"><div class="actions">'+(!S.testRoom?'<button data-write data-do="registrationMail" '+(!S.mailConfigured?'disabled data-unavailable="1"':'')+'>Auf neue Meldungen prüfen</button>':'<button data-write data-do="registrationDemo">Beispielmeldung prüfen</button>')+'<button class="quiet" data-do="registrationFile">JSON-Dateien hinzufügen</button><button class="quiet" data-do="registrationJson">JSON einfügen</button><button class="quiet" data-do="registrationRefresh">Aktualisieren / erneut prüfen</button></div><input id="registration-files" class="visually-hidden" type="file" accept=".json,application/json" multiple aria-label="Meldungsdateien auswählen"><p class="rules">'+(S.testRoom?'Alle Änderungen bleiben in diesem Testturnier.':S.mailConfigured?'Formularmeldungen und angeschlossenes Postfach werden geprüft.':'JSON-Dateien können geprüft werden.')+'</p>'+(registrationBusy?'<p role="status">Meldungen werden geprüft …</p>':registrationChecked?'<p class="rules">Zuletzt geprüft: '+esc(registrationChecked)+'</p>':'')+'</div>'+(r?'<div class="group-summary"><b>'+r.totals.newPeople+' neue Personen</b><b>'+r.totals.newEntries+' neue Starts</b><b>'+r.totals.newTeams+' neue Teams</b><span>'+r.items.filter(i=>i.status==='update').length+' Änderungen</span><span>'+r.totals.unchanged+' bereits vorhanden</span><span>'+r.totals.review+' prüfen · '+r.totals.blocked+' gesperrt</span></div>'+(r.sourceWarnings?.length?'<p class="note">'+r.sourceWarnings.map(esc).join('<br>')+'</p>':'')+'<div class="bar registration-filters"><div class="actions">'+[['open','Offene Einträge'],['all','Alle'],['unchanged','Bereits vorhanden']].map(([id,label])=>'<button class="'+(registrationFilter===id?'':'quiet')+' small-btn" data-do="registrationFilter" data-id="'+id+'" aria-pressed="'+(registrationFilter===id)+'">'+label+'</button>').join('')+'</div><input id="registration-search" class="search" placeholder="Name oder Dojo suchen" aria-label="Meldungen nach Name oder Dojo filtern" value="'+esc(registrationQuery)+'"></div><div class="actions"><button class="quiet small-btn" data-do="registrationSelectSafe">Neue und eindeutige Änderungen auswählen</button><button class="quiet small-btn" data-do="registrationSelectNone">Auswahl leeren</button></div><div class="card scroll registration-table"><table><caption>Prüfergebnis · '+registrationRows(r).length+' von '+r.items.length+' Personen / Teams</caption><thead><tr><th scope="col">Auswahl</th><th scope="col">Starter / Team</th><th scope="col">Prüfung</th><th scope="col">Vorgesehene Änderung / Korrektur</th></tr></thead><tbody>'+registrationRows(r).map(i=>'<tr><td><input type="checkbox" data-registration-select="'+i.id+'" aria-label="'+esc(i.label)+' auswählen" '+(registrationSelection.has(i.id)?'checked':'')+' '+(['blocked','unchanged'].includes(i.status)?'disabled':'')+'></td><th scope="row">'+esc(i.label)+'<small>'+esc(i.dojo)+' · '+esc(i.source)+'</small>'+(i.kind==='person'?'<small>'+esc(i.raw?.birth||'Geburtsdatum fehlt')+' · '+(i.raw?.kyu===0?'Dan':esc(i.raw?.kyu??'Grad fehlt')+'. Kyu')+'</small><button class="quiet small-btn" data-do="registrationEdit" data-id="'+i.id+'" aria-expanded="'+(registrationEdit===i.id)+'">Angaben korrigieren / zuordnen</button>':'')+'</th><td><span class="pill">'+labels[i.status]+'</span></td><td>'+(i.error?'<p class="form-warning">'+esc(i.error)+'</p>':i.changes.map(c=>'<p>'+esc(c.text)+'</p>').join('')+(i.conflicts.length?'<div class="registration-conflict">'+i.conflicts.map(c=>'<p>'+esc(c.field)+': aktuell <b>'+esc(c.current)+'</b> · gemeldet '+esc(c.incoming)+'</p>').join('')+'<label><input type="checkbox" data-registration-conflict="'+i.id+'" '+(registrationConflicts.has(i.id)?'checked':'')+'>Korrigierte Meldung statt der bisherigen Angaben übernehmen</label><small>Ohne Haken bleiben deine bisherigen Korrekturen erhalten.</small></div>':'')+(i.affected.length?'<small>Neue Auslosung: '+i.affected.map(esc).join(', ')+'</small>':'')+i.warnings.map(w=>'<small class="warning-text">'+esc(w)+'</small>').join('')+(i.status==='unchanged'?'<p class="muted">Keine erneute Übernahme erforderlich.</p>':''))+'</td></tr>'+(registrationEdit===i.id?'<tr class="registration-editor-row"><td colspan="4">'+registrationEditor(i)+'</td></tr>':'')).join('')+(!registrationRows(r).length?'<tr><td colspan="4">Keine Einträge für diesen Filter.</td></tr>':'')+'</tbody></table></div><div class="registration-apply card"><b>'+selected.length+' Einträge ausgewählt</b>'+(affected.length?'<label><input id="registration-redraw" type="checkbox">Unbegonnene Auslosungen für '+affected.map(esc).join(', ')+' erneuern</label><p class="rules">Nur ausgewählte Gruppen werden neu ausgelost.</p>':'')+'<div class="actions"><button class="green" data-write data-do="registrationApply" data-unavailable="'+(!selected.length||registrationBusy?'1':'0')+'" '+(!selected.length||registrationBusy?'disabled':'')+'>Auswahl hinzufügen / aktualisieren</button></div></div>':'<div class="card"><h2>So funktioniert es</h2><ol><li>Meldungen abrufen oder Dateien auswählen.</li><li>Neue Einträge und Änderungen prüfen; fehlerhafte Angaben direkt korrigieren.</li><li>Auswahl übernehmen. Begonnene Gruppen bleiben geschützt.</li></ol></div>');
}
function registrationEditor(item){const d=registrationEditDraft||{},candidates=matchingPeople(S.people,item),input=(name,label,type='text')=>'<label for="reg-edit-'+name+'">'+label+'<input id="reg-edit-'+name+'" name="'+name+'" type="'+type+'" value="'+esc(d[name]??'')+'" '+(name==='kyu'?'min="0" max="8" step="1"':'')+' required></label>';
 return '<form id="registration-edit-form" data-item="'+item.id+'" class="registration-editor"><h3>Korrektur · '+esc(item.label)+'</h3><div class="registration-edit-fields">'+input('first','Vorname')+input('last','Nachname')+input('birth','Geburtsdatum','date')+'<label for="reg-edit-gender">Geschlecht<select id="reg-edit-gender" name="gender"><option value="w" '+(d.gender==='w'?'selected':'')+'>Weiblich</option><option value="m" '+(d.gender==='m'?'selected':'')+'>Männlich</option></select></label>'+input('kyu','Kyu / Dan (0 = Dan)','number')+'</div><div class="fields">'+['Kata','Kumite'].map(discipline=>{const name=discipline.toLowerCase(),groups=S.groups.filter(g=>g.active&&g.type===(discipline==='Kata'?0:1)),value=d[name]||'';return '<label for="reg-edit-'+name+'">'+discipline+'-Gruppe<select name="'+name+'" id="reg-edit-'+name+'"><option value="">Kein '+discipline+'-Start</option>'+(!groups.some(g=>g.code===value)&&value?'<option selected value="'+esc(value)+'">'+esc(value)+' · ungültige Gruppe</option>':'')+groups.map(g=>'<option value="'+esc(g.code)+'" '+(g.code===value?'selected':'')+'>'+esc(g.code)+' · '+esc(groupAge(g))+' · '+esc(groupGrade(g))+'</option>').join('')+'</select></label>';}).join('')+'</div>'+(candidates.length?'<label for="reg-edit-assignment">Person mit identischem Vor- und Nachnamen zuordnen<select id="reg-edit-assignment" name="assignment"><option value="">Automatisch prüfen</option>'+candidates.map(p=>'<option value="'+esc(p.id)+'" '+(d.assignment===p.id?'selected':'')+'>'+esc(pname(p))+' · '+esc(p.birth)+' · '+(p.kyu===0?'Dan':p.kyu+'. Kyu')+'</option>').join('')+'<option value="new" '+(d.assignment==='new'?'selected':'')+'>Andere Person mit demselben Namen neu hinzufügen</option></select></label>':'')+'<p class="rules">Die Korrektur wird zuerst erneut geprüft. Im Turnier wird sie erst mit „Auswahl hinzufügen / aktualisieren“ gespeichert.</p><p id="registration-edit-error" class="form-warning" role="alert"></p><div class="actions"><button type="submit" data-write data-unavailable="'+(registrationBusy?'1':'0')+'">Korrektur prüfen</button><button type="button" class="quiet" data-do="registrationEditCancel">Abbrechen</button></div></form>';
}
function openRegistrationEditor(id){const i=registrationPreview?.items.find(i=>i.id===id);if(!i||i.kind!=='person')return;if(registrationEdit===id){registrationEdit='';registrationEditDraft=null;render();return;}registrationEdit=id;registrationEditDraft={first:i.raw?.first||'',last:i.raw?.last||'',birth:i.raw?.birth||'',gender:i.raw?.gender||'w',kyu:i.raw?.kyu??'',kata:(Array.isArray(i.raw?.starts)?i.raw.starts:[]).find(s=>s.discipline==='Kata')?.group||'',kumite:(Array.isArray(i.raw?.starts)?i.raw.starts:[]).find(s=>s.discipline==='Kumite')?.group||'',assignment:registrationAssignments[id]||''};render();$('#reg-edit-first')?.focus();}
function readRegistrationEditor(){const f=$('#registration-edit-form');if(f)registrationEditDraft=Object.fromEntries(new FormData(f));}
async function saveRegistrationEditor(){if(registrationBusy)return;const f=$('#registration-edit-form');if(!f?.reportValidity())return;readRegistrationEditor();const item=registrationPreview.items.find(i=>i.id===registrationEdit),d=registrationEditDraft,raw={...item.raw,first:d.first.trim(),last:d.last.trim(),birth:d.birth,gender:d.gender,kyu:Number(d.kyu),starts:['Kata','Kumite'].filter(name=>d[name.toLowerCase()]).map(name=>({discipline:name,group:d[name.toLowerCase()]}))};try{const replaced=replaceRegistrationPerson(registrationSource.data,item,raw),data=Array.isArray(replaced)?{records:replaced}:replaced,id=await registrationPersonId(item.dojo,raw),assignments={...registrationAssignments};delete assignments[item.id];const choice=d.assignment||(S.people.some(p=>p.id===item.entity)?item.entity:null);if(choice)assignments[id]=choice;const originals=[...(data.registrationCorrections?.[item.id]||[]),{id:item.id,dojo:item.dojo,raw:item.raw}];data.registrationCorrections={...data.registrationCorrections};delete data.registrationCorrections[item.id];data.registrationCorrections[id]=[...new Map(originals.filter(o=>o.id!==id).map(o=>[o.id,o])).values()];await checkRegistrations('file',data,assignments,{preserveSelection:true,editedId:id});toast('Korrektur geprüft. Ergebnis und Auswahl prüfen, dann übernehmen.');}catch(e){const el=$('#registration-edit-error');if(el)el.textContent=e.message;else toast(e.message);}}
async function checkRegistrations(source,data,assignments={}, {preserveSelection=false,editedId=null}={}){if(registrationBusy)return;const previousSelection=new Set(registrationSelection),previousConflicts=new Set(registrationConflicts);registrationBusy=true;if(!preserveSelection){registrationPreview=null;registrationSelection.clear();registrationConflicts.clear();registrationEdit='';registrationEditDraft=null;}render();try{await refresh(true);const checkedRun=S.runId||null,r=await api('registration-preview',{source,data,assignments});if((S.runId||null)!==checkedRun){toast('Wettkampf wurde neu begonnen. Meldungen im aktuellen Stand erneut prüfen.');return;}registrationPreview=r;registrationAssignments=r.assignments||{};registrationSource={source,data:r.data};registrationSelection=new Set(r.items.filter(i=>!['blocked','unchanged'].includes(i.status)&&(preserveSelection?previousSelection.has(i.id)||i.id===editedId&&['new','update'].includes(i.status):['new','update'].includes(i.status))).map(i=>i.id));registrationConflicts=new Set(r.items.filter(i=>preserveSelection&&previousConflicts.has(i.id)&&i.conflicts.length).map(i=>i.id));registrationEdit='';registrationEditDraft=null;registrationChecked=new Date().toLocaleString('de-DE');if(!preserveSelection){registrationFilter='open';registrationQuery='';}}catch(e){toast(e.message);throw e;}finally{registrationBusy=false;render();}}
document.addEventListener('input',e=>{if(e.target.closest('#registration-edit-form'))readRegistrationEditor();if(e.target.id==='registration-search'){registrationQuery=e.target.value;render();}});
document.addEventListener('change',e=>{if(e.target.closest('#registration-edit-form'))readRegistrationEditor();});
document.addEventListener('submit',async e=>{if(e.target.id==='registration-edit-form'){e.preventDefault();await saveRegistrationEditor();}});

async function submitRegistrations(){const r=registrationPreview;if(!r||!registrationSelection.size)return;if(S.revision!==r.revision){await checkRegistrations('file',registrationSource.data,registrationAssignments,{preserveSelection:true});toast('Der Turnierstand hat sich geändert. Bitte die neue Vorschau prüfen.');return;}if(r.items.some(i=>registrationSelection.has(i.id)&&registrationConflicts.has(i.id)&&i.conflictProtected?.length)){toast('Diese Angaben betreffen bereits begonnene Gruppen. Bitte die bestehenden Korrekturen beibehalten und die Änderung einzeln prüfen.');return;}const affected=r.items.filter(i=>registrationSelection.has(i.id)).flatMap(i=>[...i.affected,...(registrationConflicts.has(i.id)?i.conflictAffected||[]:[])]),allowRedraw=!!$('#registration-redraw')?.checked;if(affected.length&&!allowRedraw){toast('Bitte die neue Auslosung der angezeigten unbegonnenen Gruppen bestätigen.');$('#registration-redraw')?.focus();return;}const result=await act({type:'registrationSync',data:r.data,reviewedRevision:r.revision,selected:[...registrationSelection],acceptConflicts:[...registrationConflicts],assignments:registrationAssignments,allowRedraw});registrationPreview=null;registrationAssignments={};registrationEdit='';registrationEditDraft=null;registrationSelection.clear();registrationConflicts.clear();render();toast(result.people+' Personen, '+result.entries+' Starts und '+result.teams+' Teams hinzugefügt · '+result.updated+' Änderungen.'+(result.warnings.length?' Hinweise unter Wettkampffeld prüfen.':''));}
function demoRegistration(){const g=S.groups.find(g=>g.type===0&&g.minAge>=13&&g.active),age=Math.max(g.minAge,Math.min(g.maxAge,16));return {dojo:'Demo-Meldungsdojo',participants:[{first:'Neue',last:'Testmeldung',birth:(2026-age)+'-01-01',gender:g.gender==='x'?'w':g.gender,kyu:g.minKyu,starts:[{discipline:'Kata',group:g.code}]}],teams:[],fee_eur:15};}
document.addEventListener('change',async e=>{if(e.target.dataset.registrationSelect){if(e.target.checked)registrationSelection.add(e.target.dataset.registrationSelect);else registrationSelection.delete(e.target.dataset.registrationSelect);render();}if(e.target.dataset.registrationConflict){const id=e.target.dataset.registrationConflict;if(e.target.checked){registrationConflicts.add(id);registrationSelection.add(id);}else registrationConflicts.delete(id);render();}if(e.target.id==='registration-files'){try{const records=[];for(const file of e.target.files){if(file.size>2000000)throw Error(file.name+': Datei zu groß');const raw=JSON.parse(await file.text());for(const data of Array.isArray(raw)?raw:[raw])records.push({source:file.name,data});}if(records.length)await checkRegistrations('file',{records});}catch(e){toast(e.message);}}});
function shareURL(token=new URLSearchParams(location.search).get('test')){return testLink(location.href,token);}
function sharingCard(){return admin()?sharingTestCard({full:sharedLink,quick:quickLink}):'';}
function testRoleBar(){const role=S.user?.role,mat=S.user?.tatami,dojos=S.testRoom.dojos;return '<section id="test-roles" class="test-role-bar no-print" aria-label="Rollenwechsel im Test"><div class="row"><div><b>Teilbarer Turniertest · nur erfundene Daten</b><small>Aktuelle Rolle: '+esc(S.user.name)+' · gemeinsam mit allen Empfängern dieses Links</small></div><div class="actions"><button class="quiet" data-do="copyTestLink">Link kopieren</button><button data-do="testFeedback">Feedback geben</button><a class="btn quiet" href="#rehearsal">Testablauf</a></div></div><div class="test-role-buttons"><button id="test-role-admin" data-write data-do="testRole" data-role="admin" aria-pressed="'+(role==='admin')+'" class="'+(role==='admin'?'':'quiet')+'">Leitung</button>'+[1,2,3,4,5].map(i=>'<button data-write data-do="testRole" data-role="table" data-tatami="'+i+'" aria-pressed="'+(role==='table'&&mat===i)+'" class="'+(role==='table'&&mat===i?'':'quiet')+'">Tisch '+i+'</button>').join('')+'<button data-write data-do="testRole" data-role="trainer" aria-pressed="'+(role==='trainer')+'" class="'+(role==='trainer'?'':'quiet')+'">Coach</button><button data-write data-do="testRole" data-role="stream">Stream-Regie</button><button data-write data-do="testRole" data-role="public" aria-pressed="'+(role==='public')+'" class="'+(role==='public'?'':'quiet')+'">Publikum</button><label>Coach-Dojo<select id="test-dojo" aria-label="Coach-Dojo">'+dojos.map(d=>'<option '+((S.user.dojo||testDojo)===d?'selected':'')+'>'+esc(d)+'</option>').join('')+'</select></label></div></section>';}
async function switchTestRole(role,tatami,fork=false){const dojo=$('#test-dojo')?.value||testDojo;testDojo=dojo;await api('test-role',{role,fork,...(role==='table'?{tatami:Number(tatami)}:{}),...(role==='trainer'?{dojo}:{})});selectedBout='';query='';selectedGroup='';cadreEdits.clear();await refresh(true);view=role==='stream'?'stream':role==='table'?'desk':role==='trainer'?'trainer':role==='public'?'live':'rehearsal';location.hash=view;render();$('#app').focus({preventScroll:true});}
async function copyTestLink(){const link=S.testRoom?shareURL():sharedLink;if(!link)return;try{await navigator.clipboard.writeText(link);toast('Testlink kopiert · kann ohne Passwort weitergegeben werden.');}catch{form('Testlink kopieren','<label>Link zum Weitergeben<input id="copy-test-link" readonly value="'+esc(link)+'"></label><p>Strg+C kopiert den markierten Link.</p>',async()=>{});$('#copy-test-link').focus();$('#copy-test-link').select();$('#form button[type=submit]').textContent='Schließen';}}
async function feedbackForm(){if(!S.csrf)await api('test-role',{role:'public'}).then(()=>refresh(true));form('Feedback zum Turniertest','<label>Dein Name · freiwillig<input name="name" maxlength="60" autocomplete="name"></label><label>Was funktioniert gut, was ist unklar oder fehlt?<textarea name="message" maxlength="2000" required></textarea></label><p>Deine aktuelle Testrolle und die Ansicht werden mitgespeichert. Die Rückmeldungen erscheinen unter „Testablauf“ in der Rolle Leitung.</p>',f=>api('test-feedback',{...f,view,commandId:crypto.randomUUID()}));$('#form button[type=submit]').textContent='Feedback speichern';$('#form textarea').focus();}
function sharedTestView(){const m=S.testRoom.summary,feedback=S.testRoom.feedback||[];return '<p><a class="btn quiet" href="#tutorial">Tisch-Tutorial · jede Disziplin üben</a></p>'+(S.testRoom.simulation?'<section class="card"><h2>Simulation des aktuellen Turniers</h2><p>Getrennte Kopie von Stand '+S.testRoom.simulation.sourceRevision+' · Testnamen statt echter Namen. Ergebnis des Probelaufs verändert den echten Wettkampf nicht.</p></section>':'')+testTourCard(S)+'<div class="eyebrow">Gemeinsamer Testbereich</div><h1>Den ganzen Turniertag ausprobieren</h1><p class="lead">Oben eine Rolle wählen und direkt loslegen. Jeder Empfänger wählt seine eigene Rolle. Alle arbeiten am selben Testturnier mit '+m.groups+' Gruppen, Kata und Kumite im Einzel und Team.</p><div class="test-progress"><div>'+metric(m.done+' / '+m.bouts,'Begegnungen beendet')+'</div><div>'+metric(m.ratified+' / '+m.groups,'Gruppen bestätigt')+'</div><div>'+metric(S.testRoom.feedbackCount,'Rückmeldungen')+'</div></div><p class="note">'+(m.complete&&m.ratified===m.groups?'✓ Turniertest abgeschlossen · Ergebnisse und Dojorangliste sind bereit.':'Manuell am Tisch testen oder in der Rolle Leitung den Durchlauf automatisch fortsetzen.')+'</p><div class="actions test-run-controls">'+(admin()?'<button data-write data-do="testStep" data-unavailable="'+(m.complete?'1':'0')+'" '+(m.complete?'disabled':'')+'>Nächste Begegnung simulieren</button><button data-write data-do="testFinish" data-unavailable="'+(m.complete?'1':'0')+'" '+(m.complete?'disabled':'')+'>Bis zur Siegerehrung durchspielen</button><button class="quiet" data-do="testReset">Testturnier neu beginnen</button><a class="btn quiet" href="#manage">Phasen manuell freigeben</a>':'<button data-write data-do="testRole" data-role="admin">Zur Leitung wechseln</button>')+'<a class="btn quiet" href="#results">Ergebnisse ansehen</a></div><ol class="test-walkthrough"><li><b>Coach</b> · Starter und Teams des eigenen Testdojos prüfen, eine Namenskorrektur beantragen.</li><li><b>Leitung</b> · Antrag prüfen, Gruppen und Kader ansehen, Tatamis planen und die nächste Phase freigeben.</li><li><b>Tisch 1–5</b> · Starter aufrufen, Kata-Punkte mit der Tastatur erfassen, Kumite und Team-Einzelkämpfe bedienen. Zeitmarken entstehen automatisch.</li><li><b>Leitung</b> · Finals und Gruppenabschlüsse prüfen; „Bis zur Siegerehrung durchspielen“ erledigt die verbleibenden Testbegegnungen und bestätigt Ergebnisse.</li><li><b>Publikum</b> · Starterlisten, Streams, Zeitplan und Ergebnisse aus Besuchersicht ansehen.</li><li><b>Alle Rollen</b> · Über „Feedback geben“ Rückmeldungen abgeben. Ein Neustart erhält das Feedback.</li></ol><p class="rules">Dieser Testlink ist bis '+new Date(S.testRoom.expires).toLocaleDateString('de-DE')+' gültig. Ein Neustart setzt den gemeinsamen Ablauf für alle Empfänger zurück.</p>'+(admin()?'<section class="card"><h2>Gesammeltes Feedback</h2>'+(feedback.length?feedback.slice().reverse().map(f=>'<article class="feedback-item"><b>'+esc(f.name||'Ohne Namen')+'</b><small>'+esc(f.role)+' · '+esc(f.view)+' · '+esc(new Date(f.at).toLocaleString('de-DE'))+'</small><p>'+esc(f.message)+'</p></article>').join(''):'<p class="muted">Noch keine Rückmeldungen. „Feedback geben“ ist in jeder Rolle erreichbar.</p>')+'</section>':'');}
function testLeadership(){if(!admin())return denied();return '<h1>Test-Leitung</h1><button class="quiet" data-do="entry">Start hinzufügen</button><p class="lead">Gruppen prüfen, Rückmeldungen der Coach bearbeiten und Wettkampfphasen freigeben.</p><div class="actions"><a class="btn" href="#groups">Wettkampffeld</a><a class="btn quiet" href="#cadre">Kader / Setzung</a><a class="btn quiet" href="#schedule">Tatamis planen</a><a class="btn quiet" href="#all">Alle Tische</a><a class="btn quiet" href="#rehearsal">Turnierdurchlauf & Feedback</a><button class="quiet" data-do="publish">'+(S.event.published?'Publikumslisten sperren':'Publikumslisten freigeben')+'</button></div><div class="stage-list">'+phases.map((p,i)=>'<button data-write data-do="stage" data-id="'+i+'" aria-pressed="'+(S.event.stage===i)+'" class="'+(S.event.stage===i?'active':'quiet')+'">'+(i+1)+' · '+esc(p)+'</button>').join('')+'</div>'+requests();}
document.addEventListener('change',e=>{if(e.target.id==='test-dojo'){testDojo=e.target.value;if(trainer())switchTestRole('trainer').catch(e=>toast(e.message));}});
function deskKeys(){const b=S?.bouts.find(x=>x.id===selectedBout),kata=b&&[0,2].includes(group(b.group)?.type);if(kata)return '<div class="desk-shortcuts"><b>Kata · Tastatur</b><p><kbd>Enter</kbd> Kata bestätigen / weiter · <kbd>↑ ↓</kbd> Kata oder Note wählen</p><p><kbd>72</kbd> → 7,2 · automatischer Feldwechsel · <kbd>Strg Enter</kbd> speichern</p><p><kbd>'+keyLabel('pool')+'</kbd> Starterfeld / Auftritt · <kbd>'+keyLabel('fullscreen')+'</kbd> Vollbild · <kbd>'+keyLabel('special')+'</kbd> Sonderfall</p>'+gestureHelp('kata')+'</div>';return '<div class="desk-shortcuts"><div class="keyboard-side" aria-label="Bildschirmseite für Tastaturwertung">'+screenSides(S.tatamis.find(t=>t.id===(b?mat(b):S.user?.tatami||Number(sessionStorage.getItem('sdm-tatami')||1)))?.orientation||0).map((side,i)=>'<button data-do="keyboardSide" data-side="'+side+'"><kbd>'+(i?'→':'←')+'</kbd> '+(side==='aka'?'Aka':'Shiro')+'</button>').join('')+'</div><p><kbd>'+keyLabel('wazaari')+'</kbd> Wazaari · <kbd>'+keyLabel('ippon')+'</kbd> Ippon · <kbd>'+keyLabel('warning')+'</kbd> Verwarnung · <kbd>'+keyLabel('jogai')+'</kbd> Jogai · <kbd>'+keyLabel('mubobi')+'</kbd> Mubobi</p><p><kbd>Leertaste</kbd> Zeit / Start · <kbd>'+keyLabel('next')+'</kbd> Weiter · <kbd>'+keyLabel('winner')+'</kbd> Sieger · <kbd>'+keyLabel('undo')+'</kbd> Rücknahme · <kbd>'+keyLabel('fullscreen')+'</kbd> Vollbild · <kbd>'+keyLabel('pool')+'</kbd> Pool · <kbd>'+keyLabel('special')+'</kbd> Sonderfall · <kbd>'+keyLabel('repeat')+'</kbd> Wiederholung</p>'+gestureHelp('kumite')+'</div>'; }
function readyOn(t){return S.bouts.filter(b=>b.status==='ready'&&!b.held&&mat(b)===t).sort((a,b)=>(a.callRank??1e9)-(b.callRank??1e9)||phase(group(a.group),a)-phase(group(b.group),b)||jobRank(a)-jobRank(b)||(a.round||0)-(b.round||0));}
function allTables(){
 if(!admin())return denied();const bs=S.bouts||[],done=bs.filter(b=>b.status==='done').length;
 const brief=b=>'<b>'+esc(b.group)+' · '+esc(names[mode(group(b.group),b)])+'</b><p>'+ (b.shiro?'⚪ Shiro: '+esc(entrant(b.shiro).name)+'<br>🔴 Aka: ':'Kata: ')+esc(entrant(b.aka).name)+'</p>';
 return '<div class="eyebrow">Wettkampfleitung</div><h1>Alle Tische auf einen Blick</h1><p class="lead">Laufende Begegnungen, nächste Starter und Fortschritt auf allen fünf Tatamis.</p>'+(S.canReset?'<div class="actions no-print"><button class="quiet small-btn" data-write data-do="tournamentReset">Wettkampf neu beginnen</button></div>':'')+'<div class="group-summary"><b>'+bs.filter(b=>b.status==='live').length+' laufen</b><b>'+done+' von '+bs.length+' Begegnungen beendet</b><span>'+S.entries.filter(e=>e.active).length+' Starts · '+S.groups.filter(g=>g.active&&S.entries.some(e=>e.active&&e.group===g.code)).length+' belegte Gruppen</span></div><div class="all-tables">'+S.tatamis.map(t=>{const live=bs.find(b=>b.status==='live'&&mat(b)===t.id),ready=readyOn(t.id),own=bs.filter(b=>mat(b)===t.id);return '<section class="card table-summary" data-table-summary="'+t.id+'"><div class="tatami-head"><h2>Tatami '+t.id+'</h2><span class="pill '+(live?'live':'')+'">'+(live?'Läuft':'Frei')+'</span></div><h3>Jetzt</h3>'+(live?brief(live)+publicScore(live):'<p class="muted">Keine Begegnung gestartet</p>')+'<h3>Als Nächstes</h3>'+(ready[0]?brief(ready[0])+(phase(group(ready[0].group),ready[0])>S.event.stage?'<p class="warning-text">Phase noch nicht freigegeben</p>':''):'<p class="muted">Keine bereiten Begegnungen</p>')+'<p class="rules">'+own.filter(b=>b.status==='done').length+' / '+own.length+' beendet · '+ready.length+' bereit</p><div class="actions"><button data-do="switchMat" data-id="'+t.id+'">Tisch '+t.id+' öffnen</button><button class="quiet" data-do="allMatLists" data-id="'+t.id+'">Starterlisten</button></div></section>';}).join('')+'</div>'+compactDojoOverview()+queueBoard()+judgeReview();
}
function judgeReview(tatami=null){
 const bouts=S.bouts.filter(b=>b.kind==='points'&&b.status==='done'&&b.judges?.length&&(!tatami||mat(b)===tatami)).sort((a,b)=>(b.ended||'').localeCompare(a.ended||''));
 return '<section class="card"><h2>Erfasste Kampfrichterwertungen'+(tatami?' · Tatami '+tatami:' · alle Tatamis')+'</h2>'+(bouts.length?'<div class="scroll judge-review" tabindex="0" aria-label="Tabelle der Kampfrichterwertungen"><table><caption>'+bouts.length+' gespeicherte Kata-Auftritte · HKR zuerst, danach im Uhrzeigersinn</caption><thead><tr><th scope="col">Tatami / Gruppe</th><th scope="col">Starter / Team</th>'+[1,2,3,4,5,6,7].map(i=>'<th scope="col">'+(i===1?'HKR':'KR '+i)+'</th>').join('')+'<th scope="col">Gestrichen</th><th scope="col">Summe</th></tr></thead><tbody>'+bouts.map(b=>{const total=judgeSummary(b.judges.map(v=>v.toFixed(1))),decimal=v=>v.toFixed(1).replace('.',',');return '<tr><th scope="row">Tatami '+mat(b)+' · '+esc(b.group)+(b.final?'<small>Finale</small>':'')+'</th><td>'+esc(entrant(b.aka).name)+'<small>'+esc(entrant(b.aka).dojo)+' · '+esc(b.kata)+'</small></td>'+Array.from({length:7},(_,i)=>'<td>'+(b.judges[i]===undefined?'–':decimal(b.judges[i]))+'</td>').join('')+'<td>'+decimal(total.low)+' / '+decimal(total.high)+'</td><td><b>'+decimal(total.total)+'</b></td></tr>';}).join('')+'</tbody></table></div>':'<p class="muted">Noch keine Kata-Punkte gespeichert.</p>')+'</section>';
}
function draftFor(b){let draft=scoreDrafts.get(b.id);if(!draft){let count=b.judgeCount||S.bouts.find(x=>x.group===b.group&&x.kind==='points'&&!!x.final===!!b.final&&x.judges?.length)?.judges.length||(group(b.group).type===2?S.event.kataTeamJudges:S.event.kataJudges)||5;draft={kata: kataView(b).kata||allowedKata(group(b.group),b)[0]||'',count,values:Array.from({length:7},(_,i)=>kataView(b).values[i]!=null?kataView(b).values[i].toFixed(1).replace('.',','):''),version:b.version};scoreDrafts.set(b.id,draft);}return draft;}
function scoreForm(b){const d=draftFor(b),stale=d.version!==b.version;return '<form id="score-form" data-bout="'+b.id+'" class="kata-entry" aria-labelledby="score-title" novalidate><h3 id="score-title">Kampfrichterwertungen</h3><div class="fields">'+select('kata','Gezeigte Kata',options(allowedKata(group(b.group),b).map(id=>({id,name:id})),d.kata)).replace('<select','<select id="score-kata" aria-label="Gezeigte Kata"')+select('count','Kampfrichter', '<option value="5" '+(d.count===5?'selected':'')+'>5 Kampfrichter</option><option value="7" '+(d.count===7?'selected':'')+'>7 Kampfrichter</option>').replace('<select','<select id="score-count" aria-label="Kampfrichter" disabled')+'</div><p id="judge-help" class="rules">Zuerst Kata mit ↑ / ↓ wählen, Enter → erste Note. <b>72 → 7,2</b>, danach automatisch zur nächsten Note. Enter / Pfeiltasten wechseln das Feld. Live-Vorschau wird sofort übertragen; erst Speichern beendet den Auftritt.</p><fieldset class="judge-fields"><legend>Einzelwertungen · 0,0 bis 9,9</legend>'+Array.from({length:d.count},(_,i)=>'<label for="judge-'+i+'">'+(i===0?'HKR / KR 1':'KR '+(i+1))+'<input id="judge-'+i+'" name="judge'+i+'" data-judge="'+i+'" type="text" inputmode="decimal" autocomplete="off" aria-describedby="judge-help" placeholder="–" value="'+esc(d.values[i])+'" required></label>').join('')+'</fieldset><output id="judge-total" class="judge-total" aria-live="polite" aria-atomic="true"></output><p id="score-error" class="form-warning" role="alert">'+(stale?'Die Begegnung wurde inzwischen geändert. Prüfe den aktuellen Stand und die Wertungen.':'')+'</p>'+(stale?'<button type="button" class="quiet" data-do="acceptScoreVersion">Geprüft · aktuellen Stand übernehmen</button>':'')+'<div class="actions"><button id="score-save" class="green" data-write data-unavailable="1" type="submit" disabled>Wertungen speichern · weiter</button><button type="button" class="quiet" data-do="clearJudges">Wertungen leeren</button></div><p class="rules">Eine höchste und eine niedrigste Wertung werden gestrichen. <kbd>Strg</kbd> + <kbd>Enter</kbd> speichert vollständig ausgefüllte Wertungen.</p></form>';}
function updateJudgeTotal(){const f=$('#score-form');if(!f)return;const b=S.bouts.find(b=>b.id===f.dataset.bout),d=scoreDrafts.get(f.dataset.bout),total=judgeSummary(d.values.slice(0,d.count)),save=$('#score-save');$('#judge-total').textContent=total?'Summe '+total.total.toFixed(1).replace('.',',')+' · gestrichen: '+total.low.toFixed(1).replace('.',',')+' und '+total.high.toFixed(1).replace('.',','):'Noch '+d.values.slice(0,d.count).filter(v=>!judgeInput(v).complete).length+' Wertungen eingeben';save.dataset.unavailable=!total||scoreSaving||b?.status!=='live'||d.version!==b.version?'1':'0';save.disabled=!online||save.dataset.unavailable==='1';}
function focusDesk(){const el=deskPool?document.querySelector('[data-op=poolContinue]'):$('#score-kata')||$('[data-do="start"]')||$('#judge-0');el?.focus({preventScroll:false});}
async function saveJudges(f){if(scoreSaving)return;clearTimeout(previewTimer);await previewPromise;const id=f.dataset.bout,b=S.bouts.find(b=>b.id===id),d=scoreDrafts.get(id),summary=judgeSummary(d.values.slice(0,d.count));if(!summary){$('#score-error').textContent='Bitte alle fünf oder sieben Wertungen mit einer Nachkommastelle eingeben.';f.querySelector('[data-judge]:invalid')?.focus();return;}scoreSaving=true;updateJudgeTotal();try{await act({type:'bout',bout:id,version:d.version,action:'kata',kata:d.kata,judges:summary.judges});scoreDrafts.delete(id);advanceDesk(id);toast('Wertungen gespeichert · Summe '+summary.total.toFixed(1).replace('.',',')+'. Nächste Begegnung bereit.');}catch(e){const error=$('#score-error');if(error)error.textContent=e.message;else toast(e.message);}finally{scoreSaving=false;updateJudgeTotal();}}
document.addEventListener('input',e=>{const f=e.target.closest('#score-form');if(!f||e.target.dataset.judge===undefined||e.isComposing)return;const i=Number(e.target.dataset.judge),d=scoreDrafts.get(f.dataset.bout),parsed=judgeInput(e.target.value),atEnd=e.target.selectionEnd===e.target.value.length;e.target.value=parsed.text;d.values[i]=parsed.text;e.target.setAttribute('aria-invalid',parsed.text&&!parsed.complete&&!/^\d[,.]?$/.test(parsed.text)?'true':'false');updateJudgeTotal();schedulePreview();if(parsed.complete&&atEnd&&e.inputType?.startsWith('insert')){const next=$('#judge-'+(i+1))||$('#score-save');next.focus();if(next.matches('input'))next.select();}});
document.addEventListener('change',e=>{const f=e.target.closest('#score-form');if(!f)return;const d=scoreDrafts.get(f.dataset.bout);if(e.target.id==='score-kata'){d.kata=e.target.value;schedulePreview(0);}if(e.target.id==='score-count'){d.count=Number(e.target.value);sessionStorage.setItem('sdm-judges',d.count);render();$('#score-count').focus();}});
document.addEventListener('submit',e=>{if(e.target.id==='score-form'){e.preventDefault();saveJudges(e.target);}});
document.addEventListener('click',e=>{const el=e.target.closest('[data-do]');if(el?.dataset.do==='clearJudges'){const f=$('#score-form');if(!f)return;scoreDrafts.get(f.dataset.bout).values.fill('');schedulePreview(0);render();focusDesk();}if(el?.dataset.do==='allMatLists'){listMat=Number(el.dataset.id);listMode='pairings';selectedGroup='';query='';dojoFilter='';view='lists';location.hash='lists';render();}});
document.addEventListener('keydown',e=>{if(e.isComposing||e.repeat||dialog.open)return;const f=e.target.closest('#score-form');if(f&&e.target.dataset.judge!==undefined&&['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();const i=Number(e.target.dataset.judge);if(['ArrowLeft','ArrowRight'].includes(e.key)){const el=$('#judge-'+(i+(e.key==='ArrowLeft'?-1:1)))||$('#score-kata');el.focus();el.select?.();}else{const d=scoreDrafts.get(f.dataset.bout),p=judgeInput(e.target.value),n=Math.min(9.9,Math.max(0,(p.complete?p.value:7)+(e.key==='ArrowUp'?.1:-.1)));e.target.value=n.toFixed(1).replace('.',',');d.values[i]=e.target.value;updateJudgeTotal();schedulePreview();}return;}if(f&&e.target.id==='score-kata'&&e.key==='Enter'){e.preventDefault();schedulePreview(0);$('#judge-0')?.focus();return;}if(f&&e.key==='Enter'){if(e.ctrlKey){e.preventDefault();f.requestSubmit();return;}if(e.target.dataset.judge!==undefined){e.preventDefault();const parsed=judgeInput(e.target.value);if(!parsed.complete){$('#score-error').textContent='Wertung mit zwei Ziffern eingeben, z. B. 72 für 7,2.';return;}const next=$('#judge-'+(Number(e.target.dataset.judge)+1))||$('#score-save');next.focus();if(next.matches('input'))next.select();return;}}
 if(view!=='desk'||!e.altKey||e.ctrlKey||e.metaKey||e.shiftKey||e.target.closest('input,textarea,select,[contenteditable="true"]'))return;const key=e.key.toLowerCase();let el;if(key==='s')el=$('[data-do="start"]');if(key==='p')el=$('#judge-0');if(key==='n'&&!S.bouts.some(b=>b.id===selectedBout&&b.status==='live'))el=$('[data-do="nextBout"]');if(key==='t'){const b=S.bouts.find(b=>b.id===selectedBout);if(b?.status==='live')el=$('[data-do="timer"][data-running="'+(b.timer.since?'0':'1')+'"]');}if(el&&!el.disabled){e.preventDefault();if(key==='p')el.focus();else el.click();}});
function labelControls(){const labels={'search':'Starter oder Dojo suchen','overview-search':'Gruppe suchen','cadre-search':'Kaderathlet oder Dojo suchen','group-filter':'Gruppe wählen','dojo-filter':'Dojo wählen','roster-group':'Gruppe wählen','discipline-filter':'Disziplin wählen','report-pool':'Pool wählen'};for(const [id,text] of Object.entries(labels)){const el=document.getElementById(id);if(el&&!el.labels?.length&&!el.hasAttribute('aria-label'))el.setAttribute('aria-label',text);}}
function cadreView(){return cadreUI.admin();}

function resetCard(){if(!S.canReset)return '';const backups=S.resetBackups||[];return '<section class="card reset-panel"><h2>Neustart und Sicherungen</h2><p>Den Wettkampf vollständig neu aufsetzen oder mit den vorhandenen Startern und Gruppen erneut beginnen.</p><div class="actions"><button class="danger" data-write data-do="tournamentReset">Wettkampf neu beginnen</button></div><details><summary>'+backups.length+' Sicherungen vor früheren Neustarts</summary>'+(backups.length?'<div class="reset-backups">'+backups.map(b=>'<div class="queue"><b>'+esc(new Date(b.at).toLocaleString('de-DE'))+' · Stand '+b.revision+'</b><small>'+b.counts.people+' Personen · '+b.counts.teams+' Teams · '+b.counts.starts+' Starts · '+b.counts.bouts+' Begegnungen</small><div class="actions"><button class="quiet small-btn" data-do="resetBackup" data-id="'+esc(b.id)+'">Sicherung herunterladen</button><button class="quiet small-btn" data-write data-do="tournamentRestore" data-id="'+esc(b.id)+'">Diesen Stand wiederherstellen</button></div></div>').join('')+'</div>':'<p class="muted">Vor dem ersten Neustart erscheint hier automatisch die erste Sicherung.</p>')+'</details></section>';}
function resetStats(){return '<div class="reset-counts"><b>'+S.people.length+' Personen</b><b>'+S.teams.length+' Teams</b><b>'+S.entries.filter(e=>e.active).length+' aktive Starts</b><b>'+S.bouts.length+' Begegnungen</b><span>'+S.bouts.filter(b=>b.status==='live').length+' laufen gerade</span><span>'+(S.streamMarkers?.length||0)+' Stream-Zeitmarken</span></div>';}
function showTournamentReset(){if(!S.canReset)return;resetDialog='reset';form(S.testRoom?'Testturnier neu beginnen':'Wettkampf neu beginnen',resetStats()+'<fieldset class="reset-options"><legend>Wie möchtest du neu beginnen?</legend><label><input type="radio" name="mode" value="empty" checked><span><b>Vollständig neu beginnen</b><small>Alle Starter, Teams, Dojos und Meldungen leeren. Gruppenänderungen entfernen und die 86 Standardgruppen wiederherstellen.</small></span></label><label><input type="radio" name="mode" value="keep"><span><b>Vorhandene Starter und Gruppen behalten</b><small>Personendaten, Kader, Meldungen und Gruppenzuordnungen bleiben erhalten. Alle Auslosungen, Ergebnisse und Poolpläne werden aufgehoben.</small></span></label></fieldset><p class="note">Beide Optionen beginnen in der ersten Wettkampfphase. Öffentliche Listen werden gesperrt; laufende Begegnungen und aktuelle Zeitmarken werden zurückgesetzt. Deine Zugänge und Stream-Adressen bleiben erhalten.</p><p>Vor dem Neustart wird der gesamte bisherige Stand automatisch auf dem Server gesichert. Du kannst ihn anschließend herunterladen und wiederherstellen.</p><div class="actions"><button type="button" class="quiet" data-do="resetCurrentDownload">Aktuellen Stand vorher herunterladen</button></div><label class="reset-ack"><input name="acknowledged" type="checkbox" id="reset-ack">Ich habe die gewählte Option und die betroffenen Daten geprüft.</label><label for="reset-confirm">Zur Bestätigung <b>NEU STARTEN</b> eingeben<input id="reset-confirm" name="confirmation" autocomplete="off" required></label>',async f=>{const result=await act({type:'tournamentReset',mode:f.mode,confirmation:f.confirmation,acknowledged:f.acknowledged==='on'});finishResetDialog();try{await downloadResetBackup(result.backup);}catch{toast('Sicherung auf dem Server gespeichert. Download unter Neustart und Sicherungen.');}toast('Wettkampf neu begonnen · vorheriger Stand gesichert.');return false;});$('#form button[type=submit]').textContent='Gesicherten Neustart ausführen';$('#form button[type=submit]').classList.add('danger');updateResetConfirmation();}
function showTournamentRestore(id){if(!S.canReset)return;const b=S.resetBackups?.find(b=>b.id===id);if(!b)return;resetDialog='restore';form('Gesicherten Wettkampf wiederherstellen','<p><b>'+esc(new Date(b.at).toLocaleString('de-DE'))+' · Stand '+b.revision+'</b></p><p>'+b.counts.people+' Personen · '+b.counts.starts+' Starts · '+b.counts.bouts+' Begegnungen</p><p>Der aktuelle Stand wird vorher ebenfalls gesichert. Der gespeicherte Wettkampf ersetzt die aktuellen Starter, Gruppen und Ergebnisse. Wiederhergestellte Uhren bleiben angehalten und öffentliche Listen zunächst gesperrt. Aufnahmezeiten an den Tischen neu abgleichen.</p><label class="reset-ack"><input id="reset-ack" name="acknowledged" type="checkbox">Ich möchte diesen gesicherten Stand wiederherstellen.</label><label for="reset-confirm">Zur Bestätigung <b>WIEDERHERSTELLEN</b> eingeben<input id="reset-confirm" name="confirmation" autocomplete="off" required></label>',async f=>{await act({type:'tournamentRestore',backup:id,confirmation:f.confirmation,acknowledged:f.acknowledged==='on'});finishResetDialog();toast('Gesicherter Stand wiederhergestellt · Uhren angehalten, Listen gesperrt.');return false;});$('#form button[type=submit]').textContent='Gesicherten Stand wiederherstellen';updateResetConfirmation();}
function updateResetConfirmation(){if(!dialog.open||!['reset','restore'].includes(resetDialog)||!$('#reset-confirm'))return;const valid=$('#reset-ack')?.checked&&$('#reset-confirm').value.trim()===(resetDialog==='restore'?'WIEDERHERSTELLEN':'NEU STARTEN'),button=$('#form button[type=submit]');button.dataset.unavailable=valid?'0':'1';button.disabled=!online||!valid;}
